window.DAWAH={"parts":[{"id":"ahl","ic":"🕊️","name":"دعوة أهل الكتاب وأصحاب الأديان","intro":"تعريف بالإسلام وسماحته وعقيدته، والإيمان بالأنبياء جميعاً، ثم بيان الحق في مسائل الخلاف بالحجة والأدب.","topics":[{"id":"ma","t":"ما الإسلام؟","intro":"الإسلام هو الاستسلام لله وحده بالتوحيد، والانقياد له بالطاعة، والبراءة من الشرك. وهو دين الله الذي أرسل به كل الرسل، وختمه بمحمد ﷺ.","points":[{"t":"التعريف الجامع","d":"الإسلام عقيدة وعبادة وخلق: أركانه خمسة، وأركان الإيمان ستة، وأعلاه الإحسان.","ev":[{"k":"h","t":"«الإسلام أن تشهد أن لا إله إلا الله وأن محمداً رسول الله، وتقيم الصلاة، وتؤتي الزكاة، وتصوم رمضان، وتحج البيت إن استطعت إليه سبيلاً»","ref":"رواه مسلم (حديث جبريل)","id":"muslim:93"}]},{"t":"دين الله الذي ارتضاه","d":"","ev":[{"k":"q","t":"إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلْإِسْلَـٰمُ ۗ وَمَا ٱخْتَلَفَ ٱلَّذِينَ أُوتُوا۟ ٱلْكِتَـٰبَ إِلَّا مِنۢ بَعْدِ مَا جَآءَهُمُ ٱلْعِلْمُ بَغْيًۢا بَيْنَهُمْ ۗ وَمَن يَكْفُرْ بِـَٔايَـٰتِ ٱللَّهِ فَإِنَّ ٱللَّهَ سَرِيعُ ٱلْحِسَابِ ﴿19﴾","ref":"آل عمران: 19","id":"quran:3:19"},{"k":"q","t":"وَمَن يَبْتَغِ غَيْرَ ٱلْإِسْلَـٰمِ دِينًا فَلَن يُقْبَلَ مِنْهُ وَهُوَ فِى ٱلْـَٔاخِرَةِ مِنَ ٱلْخَـٰسِرِينَ ﴿85﴾","ref":"آل عمران: 85","id":"quran:3:85"}]},{"t":"رسالة للناس كافة","d":"لم يُبعث محمد ﷺ لقوم دون قوم، بل للعالمين.","ev":[{"k":"q","t":"وَمَآ أَرْسَلْنَـٰكَ إِلَّا كَآفَّةً لِّلنَّاسِ بَشِيرًا وَنَذِيرًا وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ ﴿28﴾","ref":"سبأ: 28","id":"quran:34:28"},{"k":"q","t":"وَمَآ أَرْسَلْنَـٰكَ إِلَّا رَحْمَةً لِّلْعَـٰلَمِينَ ﴿107﴾","ref":"الأنبياء: 107","id":"quran:21:107"}]}]},{"id":"anbiya","t":"الإيمان بجميع الأنبياء","intro":"لا يصح إسلام أحد حتى يؤمن بجميع الأنبياء: نوح وإبراهيم وموسى وعيسى ومحمد وغيرهم، عليهم الصلاة والسلام، ودينهم واحد هو التوحيد.","points":[{"t":"لا نفرق بين أحد من رسله","d":"","ev":[{"k":"q","t":"قُولُوٓا۟ ءَامَنَّا بِٱللَّهِ وَمَآ أُنزِلَ إِلَيْنَا وَمَآ أُنزِلَ إِلَىٰٓ إِبْرَٰهِـۧمَ وَإِسْمَـٰعِيلَ وَإِسْحَـٰقَ وَيَعْقُوبَ وَٱلْأَسْبَاطِ وَمَآ أُوتِىَ مُوسَىٰ وَعِيسَىٰ وَمَآ أُوتِىَ ٱلنَّبِيُّونَ مِن رَّبِّهِمْ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّنْهُمْ وَنَحْنُ لَهُۥ مُسْلِمُونَ ﴿136﴾","ref":"البقرة: 136","id":"quran:2:136"},{"k":"q","t":"ءَامَنَ ٱلرَّسُولُ بِمَآ أُنزِلَ إِلَيْهِ مِن رَّبِّهِۦ وَٱلْمُؤْمِنُونَ ۚ كُلٌّ ءَامَنَ بِٱللَّهِ وَمَلَـٰٓئِكَتِهِۦ وَكُتُبِهِۦ وَرُسُلِهِۦ لَا نُفَرِّقُ بَيْنَ أَحَدٍ مِّن رُّسُلِهِۦ ۚ وَقَالُوا۟ سَمِعْنَا وَأَطَعْنَا ۖ غُفْرَانَكَ رَبَّنَا وَإِلَيْكَ ٱلْمَصِيرُ ﴿285﴾","ref":"البقرة: 285","id":"quran:2:285"}]},{"t":"دين الأنبياء واحد","d":"الشرائع تختلف، والأصل واحد: عبادة الله وحده.","ev":[{"k":"h","t":"«الأنبياء إخوة لعلّات: أمهاتهم شتى، ودينهم واحد»","ref":"متفق عليه","id":"bukhari:3442"},{"k":"q","t":"شَرَعَ لَكُم مِّنَ ٱلدِّينِ مَا وَصَّىٰ بِهِۦ نُوحًا وَٱلَّذِىٓ أَوْحَيْنَآ إِلَيْكَ وَمَا وَصَّيْنَا بِهِۦٓ إِبْرَٰهِيمَ وَمُوسَىٰ وَعِيسَىٰٓ ۖ أَنْ أَقِيمُوا۟ ٱلدِّينَ وَلَا تَتَفَرَّقُوا۟ فِيهِ ۚ كَبُرَ عَلَى ٱلْمُشْرِكِينَ مَا تَدْعُوهُمْ إِلَيْهِ ۚ ٱللَّهُ يَجْتَبِىٓ إِلَيْهِ مَن يَشَآءُ وَيَهْدِىٓ إِلَيْهِ مَن يُنِيبُ ﴿13﴾","ref":"الشورى: 13","id":"quran:42:13"},{"k":"b","t":"… وفيها ما يختص به محمد صلى الله عليه وسلم من الشرعة والمنهاج. فإن دين الأنبياء واحد كما ثبت في الصحيح عن النبي صلى الله عليه وسلم أنه قال: «إنا - معشر الأنبياء - ديننا واحد» ، قال الله تعالى: {شرع لكم من الدين ما وصى به نوحا والذي أوحينا إليك وما وصينا به إبراهيم وموسى وعيسى أن أقيموا الدين ولا تتفرقوا فيه} [الشورى: 13] . وقال تعالى: {ياأيها الرسل كلوا من الطيبات واعملوا صالحا إني بما تعملون عليم - وإن …","ref":"ابن تيمية في «الجواب الصحيح»","id":"jawab-sahih:239","sec":"فصل: براهين قرآنية مستقلة على نبوته صلى الله عليه وسلم (2)"}]}]},{"id":"masih","t":"المسيح وأمه عليهما السلام في الإسلام","intro":"يحب المسلمون المسيح عيسى ابن مريم ويؤمنون به نبياً كريماً من أولي العزم، وبأمه الصدّيقة الطاهرة، وبمعجزاته، وبرفعه، وبنزوله آخر الزمان.","points":[{"t":"البشارة بالمسيح ومكانة مريم","d":"","ev":[{"k":"q","t":"وَإِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ ٱصْطَفَىٰكِ وَطَهَّرَكِ وَٱصْطَفَىٰكِ عَلَىٰ نِسَآءِ ٱلْعَـٰلَمِينَ ﴿42﴾","ref":"آل عمران: 42","id":"quran:3:42"},{"k":"q","t":"إِذْ قَالَتِ ٱلْمَلَـٰٓئِكَةُ يَـٰمَرْيَمُ إِنَّ ٱللَّهَ يُبَشِّرُكِ بِكَلِمَةٍ مِّنْهُ ٱسْمُهُ ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ وَجِيهًا فِى ٱلدُّنْيَا وَٱلْـَٔاخِرَةِ وَمِنَ ٱلْمُقَرَّبِينَ ﴿45﴾","ref":"آل عمران: 45","id":"quran:3:45"}]},{"t":"سورة باسم مريم","d":"","ev":[{"k":"q","t":"قَالَ إِنِّى عَبْدُ ٱللَّهِ ءَاتَىٰنِىَ ٱلْكِتَـٰبَ وَجَعَلَنِى نَبِيًّا ﴿30﴾ وَجَعَلَنِى مُبَارَكًا أَيْنَ مَا كُنتُ وَأَوْصَـٰنِى بِٱلصَّلَوٰةِ وَٱلزَّكَوٰةِ مَا دُمْتُ حَيًّا ﴿31﴾ وَبَرًّۢا بِوَٰلِدَتِى وَلَمْ يَجْعَلْنِى جَبَّارًا شَقِيًّا ﴿32﴾ وَٱلسَّلَـٰمُ عَلَىَّ يَوْمَ وُلِدتُّ وَيَوْمَ أَمُوتُ وَيَوْمَ أُبْعَثُ حَيًّا ﴿33﴾","ref":"مريم: 30–33","id":"quran:19:30"}]},{"t":"نحن أولى الناس بعيسى","d":"","ev":[{"k":"h","t":"«أنا أولى الناس بعيسى ابن مريم في الدنيا والآخرة، والأنبياء إخوة لعلّات»","ref":"متفق عليه","id":"bukhari:3443"}]}]},{"id":"sawa","t":"الكلمة السواء: دعوة إلى التوحيد","intro":"أساس الدعوة مع أهل الكتاب: الاتفاق على عبادة الله وحده، وهي الكلمة التي كتب بها النبي ﷺ إلى هرقل عظيم الروم.","points":[{"t":"الآية الجامعة","d":"","ev":[{"k":"q","t":"قُلْ يَـٰٓأَهْلَ ٱلْكِتَـٰبِ تَعَالَوْا۟ إِلَىٰ كَلِمَةٍ سَوَآءٍۭ بَيْنَنَا وَبَيْنَكُمْ أَلَّا نَعْبُدَ إِلَّا ٱللَّهَ وَلَا نُشْرِكَ بِهِۦ شَيْـًٔا وَلَا يَتَّخِذَ بَعْضُنَا بَعْضًا أَرْبَابًا مِّن دُونِ ٱللَّهِ ۚ فَإِن تَوَلَّوْا۟ فَقُولُوا۟ ٱشْهَدُوا۟ بِأَنَّا مُسْلِمُونَ ﴿64﴾","ref":"آل عمران: 64","id":"quran:3:64"}]},{"t":"كتاب النبي ﷺ إلى هرقل","d":"","ev":[{"k":"h","t":"«أسلم تسلم، يؤتك الله أجرك مرتين، فإن توليت فإن عليك إثم الأريسيين»","ref":"متفق عليه","id":"bukhari:7"},{"k":"b","t":"… الله إلى هرقل عظيم الروم، السلام على من اتبع الهدى، أما بعد: فأسلم تسلم، وأسلم يؤتك الله أجرك مرتين، وإن توليت فإن عليك إثم الأريسيين» يعني الأكارين. قال ابن إسحاق، وقال ابن شهاب: حدثني أسقف النصارى في زمان عبد الملك بن مروان، زعم لي أنه أدرك ذلك من أمر رسول الله صلى الله عليه وسلم، وأمر هرقل وعقله، قال: لما قدم عليه كتاب رسول الله صلى الله عليه وسلم مع دحية أخذه فجعله على خاصرته، ثم كتب إلى …","ref":"ابن تيمية: إرسال الرسل إلى الملوك","id":"jawab-sahih:26","sec":"إرسال الرسل إلى جميع الطوائف الموجودة في عهده"}]}]},{"id":"samaha","t":"سماحة الإسلام وعدله مع غير المسلمين","intro":"الإسلام لا يُكره أحداً على الدخول فيه، ويأمر بالبر والعدل مع المسالمين، ويحرّم الاعتداء على المعاهَد.","points":[{"t":"لا إكراه في الدين","d":"","ev":[{"k":"q","t":"لَآ إِكْرَاهَ فِى ٱلدِّينِ ۖ قَد تَّبَيَّنَ ٱلرُّشْدُ مِنَ ٱلْغَىِّ ۚ فَمَن يَكْفُرْ بِٱلطَّـٰغُوتِ وَيُؤْمِنۢ بِٱللَّهِ فَقَدِ ٱسْتَمْسَكَ بِٱلْعُرْوَةِ ٱلْوُثْقَىٰ لَا ٱنفِصَامَ لَهَا ۗ وَٱللَّهُ سَمِيعٌ عَلِيمٌ ﴿256﴾","ref":"البقرة: 256","id":"quran:2:256"}]},{"t":"البر والقسط مع المسالمين","d":"","ev":[{"k":"q","t":"لَّا يَنْهَىٰكُمُ ٱللَّهُ عَنِ ٱلَّذِينَ لَمْ يُقَـٰتِلُوكُمْ فِى ٱلدِّينِ وَلَمْ يُخْرِجُوكُم مِّن دِيَـٰرِكُمْ أَن تَبَرُّوهُمْ وَتُقْسِطُوٓا۟ إِلَيْهِمْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُقْسِطِينَ ﴿8﴾","ref":"الممتحنة: 8","id":"quran:60:8"}]},{"t":"حرمة المعاهَد","d":"","ev":[{"k":"h","t":"«من قتل معاهَداً لم يرح رائحة الجنة»","ref":"رواه البخاري","id":"bukhari:3166"}]},{"t":"العدل ولو مع المخالف","d":"","ev":[{"k":"q","t":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ كُونُوا۟ قَوَّٰمِينَ لِلَّهِ شُهَدَآءَ بِٱلْقِسْطِ ۖ وَلَا يَجْرِمَنَّكُمْ شَنَـَٔانُ قَوْمٍ عَلَىٰٓ أَلَّا تَعْدِلُوا۟ ۚ ٱعْدِلُوا۟ هُوَ أَقْرَبُ لِلتَّقْوَىٰ ۖ وَٱتَّقُوا۟ ٱللَّهَ ۚ إِنَّ ٱللَّهَ خَبِيرٌۢ بِمَا تَعْمَلُونَ ﴿8﴾","ref":"المائدة: 8","id":"quran:5:8"}]}]},{"id":"nubuwwa","t":"أدلة نبوة محمد ﷺ","intro":"من أدلة نبوته: القرآن المعجز الذي تحدّى به العرب، وصدقه وأمانته المشهودة، وتحقق أخباره، والبشارات به في الكتب السابقة.","points":[{"t":"التحدي بالقرآن","d":"","ev":[{"k":"q","t":"وَإِن كُنتُمْ فِى رَيْبٍ مِّمَّا نَزَّلْنَا عَلَىٰ عَبْدِنَا فَأْتُوا۟ بِسُورَةٍ مِّن مِّثْلِهِۦ وَٱدْعُوا۟ شُهَدَآءَكُم مِّن دُونِ ٱللَّهِ إِن كُنتُمْ صَـٰدِقِينَ ﴿23﴾","ref":"البقرة: 23","id":"quran:2:23"},{"k":"q","t":"قُل لَّئِنِ ٱجْتَمَعَتِ ٱلْإِنسُ وَٱلْجِنُّ عَلَىٰٓ أَن يَأْتُوا۟ بِمِثْلِ هَـٰذَا ٱلْقُرْءَانِ لَا يَأْتُونَ بِمِثْلِهِۦ وَلَوْ كَانَ بَعْضُهُمْ لِبَعْضٍ ظَهِيرًا ﴿88﴾","ref":"الإسراء: 88","id":"quran:17:88"}]},{"t":"البشارة به في الكتب السابقة","d":"","ev":[{"k":"q","t":"ٱلَّذِينَ يَتَّبِعُونَ ٱلرَّسُولَ ٱلنَّبِىَّ ٱلْأُمِّىَّ ٱلَّذِى يَجِدُونَهُۥ مَكْتُوبًا عِندَهُمْ فِى ٱلتَّوْرَىٰةِ وَٱلْإِنجِيلِ يَأْمُرُهُم بِٱلْمَعْرُوفِ وَيَنْهَىٰهُمْ عَنِ ٱلْمُنكَرِ وَيُحِلُّ لَهُمُ ٱلطَّيِّبَـٰتِ وَيُحَرِّمُ عَلَيْهِمُ ٱلْخَبَـٰٓئِثَ وَيَضَعُ عَنْهُمْ إِصْرَهُمْ وَٱلْأَغْلَـٰلَ ٱلَّتِى كَانَتْ عَلَيْهِمْ ۚ فَٱلَّذِينَ ءَامَنُوا۟ بِهِۦ وَعَزَّرُوهُ وَنَصَرُوهُ وَٱتَّبَعُوا۟ ٱلنُّورَ ٱلَّذِىٓ أُنزِلَ مَعَهُۥٓ ۙ أُو۟لَـٰٓئِكَ هُمُ ٱلْمُفْلِحُونَ ﴿157﴾","ref":"الأعراف: 157","id":"quran:7:157"},{"k":"q","t":"وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ ﴿6﴾","ref":"الصف: 6","id":"quran:61:6"},{"k":"b","t":"… صوته بالشهادة لأخيه وأولى الناس به بأنه عبد الله ورسوله، وأنه أركون العالم، وأنه روح الحق الذي لا يتكلم من قبل نفسه، إنما يقول ما يقال له، وأنه يخبر الناس بكل ما أعد الله لهم، ويسوسهم بالحق، ويخبرهم بالغيوب ويحييهم بالتأويل، ويوبخ العالم على الخطيئة، ويخلصهم من يد الشيطان، وتستمر شريعته وسلطانه إلى آخر الدهر، وصرح في آذانه باسمه ونعته، وصفته وسيرته، حتى كأنهم ينظرون إليه عيانا، ثم قال حي على …","ref":"ابن القيم في «هداية الحيارى»: البشارات في الإنجيل","id":"hidayat-hayara:1","sec":"مقدمة"},{"k":"b","t":"… من السفر الأول من التوراة مخاطبا إبراهيم الخليل عليه السلام وأما في إسماعيل فقد قبلت دعاءك ها أنا قد باركت فيه وأثمره وأكثره جدا جدا ذلك قوله وليشماعيل شمعيتخا هني يبرختي أونوا وهفريثي أوثو وهز بيثي أوثو بمادماد فهذه الكلمة بمادماد إذا عددنا حساب حروفها بالجمل كان اثنين وتسعين وذلك عدد حساب حروف اسم محمد صلى الله عليه وسلم فإنه أيضا اثنان وتسعون وإنما جعل ذلك في هذا الموضوع ملغزا لأنه لو صرح به لبدلته اليهود …","ref":"السموأل المغربي (وكان يهودياً فأسلم): البشارة في التوراة","id":"ifham-yahud:15","sec":"الإشارة إلى اسمه في التوراة"}]},{"t":"لا يصح الإيمان بموسى وعيسى مع تكذيبه","d":"","ev":[{"k":"b","t":"… في موضع آخر لم نبسطها هنا ; لأن جواب كلامهم لا يحتاج إلى ذلك فيمتنع الإقرار بنبوة موسى وعيسى - عليهما السلام - مع التكذيب بنبوة محمد - صلى الله عليه وسلم - ولا يفعل ذلك إلا من هو من أجهل الناس وأضلهم أو من أعظمهم عنادا واتباعا لهواه وذلك أن هؤلاء القوم احتجوا بما نقلوه عن الأنبياء ولم يذكروا الأدلة الدالة على صدقهم بل أخذوا ذلك مسلما وطلبوا أن يحتجوا بما نقلوه عن الأنبياء قبله وبما نقلوه عنه على صحة دينهم …","ref":"ابن تيمية في «الجواب الصحيح»","id":"jawab-sahih:42","sec":"فصل: إن لم يقروا برسالته إلى العرب"}]}]},{"id":"hifz","t":"حفظ القرآن، وما وقع في الكتب السابقة","intro":"تكفّل الله بحفظ القرآن، ولم يتكفل بحفظ الكتب السابقة، بل استحفظها أهلها فوقع فيها التغيير؛ ولهذا يؤمن المسلم بأصلها المنزل، ويحكم عليها بالقرآن المهيمن.","points":[{"t":"حفظ القرآن","d":"","ev":[{"k":"q","t":"إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ ﴿9﴾","ref":"الحجر: 9","id":"quran:15:9"},{"k":"b","t":"… الزلازل العظيمة والمحاربات الشديدة والأمور النادرة، ولما كان اهتمام المسلمين بحفظ القرآن في كل قرن، يوجد فيهم من حفاظ القرآن في هذا العصر أيضا أزيد من مائة ألف في الديار الإسلامية كلها وإن زالت سلطنة أهل الإسلام من أكثر أقطار الممالك ووقع الفتور في الأمور الدينية في أكبر أقطارهم ومن كان شاكا في هذا الأمر من المسيحيين فليجرب وليدخل في الجامع الأزهر فقط فيجد في كل وقت أكثر من ألف حافظ من حفاظ القرآن الذين حفظوه …","ref":"رحمة الله الهندي في «إظهار الحق»","id":"izhar-haqq:514","sec":"الفائدة الثانية"}]},{"t":"القرآن مهيمن على ما قبله","d":"","ev":[{"k":"q","t":"وَأَنزَلْنَآ إِلَيْكَ ٱلْكِتَـٰبَ بِٱلْحَقِّ مُصَدِّقًا لِّمَا بَيْنَ يَدَيْهِ مِنَ ٱلْكِتَـٰبِ وَمُهَيْمِنًا عَلَيْهِ ۖ فَٱحْكُم بَيْنَهُم بِمَآ أَنزَلَ ٱللَّهُ ۖ وَلَا تَتَّبِعْ أَهْوَآءَهُمْ عَمَّا جَآءَكَ مِنَ ٱلْحَقِّ ۚ لِكُلٍّ جَعَلْنَا مِنكُمْ شِرْعَةً وَمِنْهَاجًا ۚ وَلَوْ شَآءَ ٱللَّهُ لَجَعَلَكُمْ أُمَّةً وَٰحِدَةً وَلَـٰكِن لِّيَبْلُوَكُمْ فِى مَآ ءَاتَىٰكُمْ ۖ فَٱسْتَبِقُوا۟ ٱلْخَيْرَٰتِ ۚ إِلَى ٱللَّهِ مَرْجِعُكُمْ جَمِيعًا فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ ﴿48﴾","ref":"المائدة: 48","id":"quran:5:48"}]},{"t":"ما وقع من التبديل","d":"","ev":[{"k":"q","t":"فَوَيْلٌ لِّلَّذِينَ يَكْتُبُونَ ٱلْكِتَـٰبَ بِأَيْدِيهِمْ ثُمَّ يَقُولُونَ هَـٰذَا مِنْ عِندِ ٱللَّهِ لِيَشْتَرُوا۟ بِهِۦ ثَمَنًا قَلِيلًا ۖ فَوَيْلٌ لَّهُم مِّمَّا كَتَبَتْ أَيْدِيهِمْ وَوَيْلٌ لَّهُم مِّمَّا يَكْسِبُونَ ﴿79﴾","ref":"البقرة: 79","id":"quran:2:79"},{"k":"b","t":"… مسلم أن ينكره أشد الإنكار، وثبت أن الغلط والاختلاف والتناقض والتحريف واقعة فيها جزما فإني معذور في أن أقول: إن هذه الكتب ليست كتبا إلهية وأن أنكر بعض القصص مثل: أن لوطا شرب الخمر وزنى بابنتيه وحملتا بالزنا منه، أو أن داود عليه السلام زنا بامرأة أوريا وحملت بالزنا منه، وأشار إلى أمير العسكر لأن يدبر أمرا يقتل به أوريا فأهلكه بالحيلة، وتصرف في زوجته، وأن هارون صنع عجلا وبنى له مذبحا فعبده هارون مع بني …","ref":"إظهار الحق: باب التحريف","id":"izhar-haqq:6","sec":"الرابع"}]}]},{"id":"tathlith","t":"التوحيد ومسألة التثليث","intro":"نخاطب إخواننا النصارى بالعقل ونصوص المسيح نفسه: فالمسيح عبد الله ورسوله، كان يأكل الطعام ويدعو ربه، والتثليث معناه تعدد يناقض الوحدانية.","points":[{"t":"آيات في المسيح والتثليث","d":"","ev":[{"k":"q","t":"يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ ۖ سُبْحَـٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ ۘ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿171﴾","ref":"النساء: 171","id":"quran:4:171"},{"k":"q","t":"لَّقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ ثَالِثُ ثَلَـٰثَةٍ ۘ وَمَا مِنْ إِلَـٰهٍ إِلَّآ إِلَـٰهٌ وَٰحِدٌ ۚ وَإِن لَّمْ يَنتَهُوا۟ عَمَّا يَقُولُونَ لَيَمَسَّنَّ ٱلَّذِينَ كَفَرُوا۟ مِنْهُمْ عَذَابٌ أَلِيمٌ ﴿73﴾","ref":"المائدة: 73","id":"quran:5:73"},{"k":"q","t":"مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ ۖ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ۗ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَـٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ ﴿75﴾","ref":"المائدة: 75","id":"quran:5:75"}]},{"t":"الحجة العقلية","d":"","ev":[{"k":"b","t":"… أسماء السلوب فإذا وصفنا بها موجودا فقد نفينا عنه التعدد والكثرة والتثليث معناه تعدد وكثرة فإذا أضاف هذا القائل التثليث للوحدة فكأنه قال تكثير مالا يتكثر وتكثير مالا يتكثر باطل بالضرورة فأول كلمة تكلم بها هذا السائل متناقضة وباطلة بالضرورة وأما قوله في معرفة الله فقول لم يحط بمعناه ولا فهم مسماه وإلا فما حد المعرفة وكم أقسامها وهل يصح أن تكون مكتسبة لنا وهل يجوز عقلا أن يكلفنا بها الأنبياء وإن جاز ذلك فما طريق …","ref":"القرطبي في «الإعلام بما في دين النصارى»","id":"iclam-nasara:3","sec":"فصل"},{"k":"b","t":"… ويخرج منها من وجه آخر النصارى فأما الوجه الذي يدخلون به فهو قولهم بالتثليث وأن خالق الخلق ثلاثة وأما الوجه الذي يخرجون به فهو أن للصابئين شرائع يسندونها إلى هرمس ويقولون أنه إدريس وإلى قوم آخر يذكرون أنهم أنبياء كايلون ويقولون أنه نوح عليه السلام واسفلانيوس صاحب الهيكل الموصوف وعاظميون ويوداسف وغيرهم والنصارى لا يعرفون هؤلاء لكن يقرون بنبوة نبي تعرفه من بني إسرائيل وإبراهيم وإسحاق ويعقوب عليهم …","ref":"ابن حزم في «الفِصَل»","id":"fisal:6","sec":"الكلام على من قال أن فاعل العالم ومدبره أكثر من واحد (1)"}]},{"t":"المسيح يدعو إلى عبادة الله وحده","d":"","ev":[{"k":"q","t":"وَإِذْ قَالَ ٱللَّهُ يَـٰعِيسَى ٱبْنَ مَرْيَمَ ءَأَنتَ قُلْتَ لِلنَّاسِ ٱتَّخِذُونِى وَأُمِّىَ إِلَـٰهَيْنِ مِن دُونِ ٱللَّهِ ۖ قَالَ سُبْحَـٰنَكَ مَا يَكُونُ لِىٓ أَنْ أَقُولَ مَا لَيْسَ لِى بِحَقٍّ ۚ إِن كُنتُ قُلْتُهُۥ فَقَدْ عَلِمْتَهُۥ ۚ تَعْلَمُ مَا فِى نَفْسِى وَلَآ أَعْلَمُ مَا فِى نَفْسِكَ ۚ إِنَّكَ أَنتَ عَلَّـٰمُ ٱلْغُيُوبِ ﴿116﴾ مَا قُلْتُ لَهُمْ إِلَّا مَآ أَمَرْتَنِى بِهِۦٓ أَنِ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۚ وَكُنتُ عَلَيْهِمْ شَهِيدًا مَّا دُمْتُ فِيهِمْ ۖ فَلَمَّا تَوَفَّيْتَنِى كُنتَ أَنتَ ٱلرَّقِيبَ عَلَيْهِمْ ۚ وَأَنتَ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ ﴿117﴾","ref":"المائدة: 116–117","id":"quran:5:116"},{"k":"b","t":"… بالضرب والإهانة والشوك والصلب والقتل بزعمكم وهو مع ذلك يقول {اعبدوا الله ربي وربكم} ويقول لكم إذا صليتم فقولوا يا أبانا السماوي تقدس اسمك وقرب ملكك ويقول إن الله وحده ولا إله إلا هو ويقول لإبليس إنما أمرت أن تعبد السيد إلهك وحده ويقول حين قرب رفعه وأعلمه الله به سيلقى ابن الإنسان ما كتب له يعنى نفسه ثم تقدم وسجد على الأرض ودعى أن يزاح عنه ما هو فيه وقال يا أبتاه إنك قادر على جميع الأشياء فرج عني هذه …","ref":"القرطبي","id":"iclam-nasara:30","sec":"الجواب عنه"}]}]},{"id":"salb","t":"العدل الإلهي ومسألة الصلب والفداء","intro":"يؤمن المسلمون أن المسيح لم يُقتل ولم يُصلب بل رفعه الله، وأن كل نفس تحمل عملها، فلا يؤاخَذ أحد بذنب غيره، وباب التوبة مفتوح بلا وسيط.","points":[{"t":"رفع المسيح","d":"","ev":[{"k":"q","t":"وَقَوْلِهِمْ إِنَّا قَتَلْنَا ٱلْمَسِيحَ عِيسَى ٱبْنَ مَرْيَمَ رَسُولَ ٱللَّهِ وَمَا قَتَلُوهُ وَمَا صَلَبُوهُ وَلَـٰكِن شُبِّهَ لَهُمْ ۚ وَإِنَّ ٱلَّذِينَ ٱخْتَلَفُوا۟ فِيهِ لَفِى شَكٍّ مِّنْهُ ۚ مَا لَهُم بِهِۦ مِنْ عِلْمٍ إِلَّا ٱتِّبَاعَ ٱلظَّنِّ ۚ وَمَا قَتَلُوهُ يَقِينًۢا ﴿157﴾ بَل رَّفَعَهُ ٱللَّهُ إِلَيْهِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا ﴿158﴾","ref":"النساء: 157–158","id":"quran:4:157"}]},{"t":"لا تزر وازرة وزر أخرى","d":"","ev":[{"k":"q","t":"قُلْ أَغَيْرَ ٱللَّهِ أَبْغِى رَبًّا وَهُوَ رَبُّ كُلِّ شَىْءٍ ۚ وَلَا تَكْسِبُ كُلُّ نَفْسٍ إِلَّا عَلَيْهَا ۚ وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ ثُمَّ إِلَىٰ رَبِّكُم مَّرْجِعُكُمْ فَيُنَبِّئُكُم بِمَا كُنتُمْ فِيهِ تَخْتَلِفُونَ ﴿164﴾","ref":"الأنعام: 164","id":"quran:6:164"},{"k":"q","t":"أَلَّا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ﴿38﴾ وَأَن لَّيْسَ لِلْإِنسَـٰنِ إِلَّا مَا سَعَىٰ ﴿39﴾","ref":"النجم: 38–39","id":"quran:53:38"}]},{"t":"التوبة بلا وسيط","d":"","ev":[{"k":"q","t":"قُلْ يَـٰعِبَادِىَ ٱلَّذِينَ أَسْرَفُوا۟ عَلَىٰٓ أَنفُسِهِمْ لَا تَقْنَطُوا۟ مِن رَّحْمَةِ ٱللَّهِ ۚ إِنَّ ٱللَّهَ يَغْفِرُ ٱلذُّنُوبَ جَمِيعًا ۚ إِنَّهُۥ هُوَ ٱلْغَفُورُ ٱلرَّحِيمُ ﴿53﴾","ref":"الزمر: 53","id":"quran:39:53"},{"k":"q","t":"وَإِذَا سَأَلَكَ عِبَادِى عَنِّى فَإِنِّى قَرِيبٌ ۖ أُجِيبُ دَعْوَةَ ٱلدَّاعِ إِذَا دَعَانِ ۖ فَلْيَسْتَجِيبُوا۟ لِى وَلْيُؤْمِنُوا۟ بِى لَعَلَّهُمْ يَرْشُدُونَ ﴿186﴾","ref":"البقرة: 186","id":"quran:2:186"}]}]},{"id":"aslamu","t":"من أسلم من علمائهم وكبرائهم","intro":"أسلم كثير من أحبار اليهود ورهبان النصارى لما تبيّن لهم الحق: عبد الله بن سلام، وسلمان الفارسي، وعدي بن حاتم، والنجاشي، وغيرهم.","points":[{"t":"عبد الله بن سلام","d":"","ev":[{"k":"b","t":"… وابن سيدهم، وعالمهم وابن عالمهم، باعترافهم له بذلك، وشهادتهم، وهو عبد الله بن سلام، لكان في مقابلة كل يهودي على وجه الأرض، فكيف وقد تابعه على الإسلام من الأحبار والرهبان من لا يحصي عددهم إلا الله. إسلام عبد الله بن سلام سيد اليهود ونحن نذكر قصة عبد الله بن سلام. فروى البخاري في صحيحه من حديث عبد العزيز بن صهيب، عن أنس بن مالك، رضي الله عنهم، قال أقبل رسول الله صلى الله عليه وسلم إلى المدينة، فقيل: جاء …","ref":"ابن القيم في «هداية الحيارى»","id":"hidayat-hayara:16","sec":"فصل) : ونحن إنما ذكرنا بعض ملوك الطوائف الذي آمنوا به، وأكابر علمائهم وعظمائهم، ولا يمكننا حصر من عداهم"}]},{"t":"سلمان الفارسي وعدي بن حاتم","d":"","ev":[{"k":"b","t":"… ووالله لتكونن الثالثة. إنه حديث رسول الله صلى الله عليه وسلم. وقد كان سلمان الفارسي من أعلم النصارى بدينهم، وكان قد تيقن خروج النبي صلى الله عليه وسلم فقدم المدينة قبل مبعثه، فلما رآه عرف أنه هو النبي الذي بشر به المسيح فآمن به واتبعه، ونحن نسوق قصته. قال ابن إسحاق: حدثني عاصم، عن محمود، عن ابن عباس رضي الله عنهما، قال: حدثني سلمان من فيه، قال: كنت رجلا فارسيا من أهل أصبهان من قرية يقال لها: (حي) . وكان …","ref":"ابن القيم","id":"hidayat-hayara:11","sec":"فصل) : وكان من رؤساء النصارى الذين دخلوا في الإسلام لما تبين لهم أنه الحق، الرئيس المطاع في قومه عدي بن حاتم الطائي."},{"k":"b","t":"ونحن نذكر قصته كما رواها الإمام أحمد والترمذي والحاكم وغيرهم. قال عدي بن حاتم: أتيت النبي صلى الله عليه وسلم وهو جالس في المسجد، فقال القوم: هذا عدي بن حاتم - وجئت بغير أمان ولا كتاب - فلما دفعت إليه أخذ بيدي، وقد كان قبل ذلك قال: إني لأرجو أن يجعل الله يده في يدي، قال: فقام، فلقيته امرأة وصبي معها، فقالا: إن لنا إليك حاجة، فقام معهما حتى قضى حاجتها، ثم أخذ بيدي حتى أتى بي داره فألقت له الوليدة وسادة، فجلس …","ref":"ابن القيم","id":"hidayat-hayara:11","sec":"فصل) : وكان من رؤساء النصارى الذين دخلوا في الإسلام لما تبين لهم أنه الحق، الرئيس المطاع في قومه عدي بن حاتم الطائي."}]}]},{"id":"adab","t":"أدب الحوار مع أهل الأديان","intro":"الحوار بالتي هي أحسن، بلا سبّ لمعبوداتهم، مع العدل والإنصاف ومراعاة المشاعر.","points":[{"t":"بالتي هي أحسن","d":"","ev":[{"k":"q","t":"وَلَا تُجَـٰدِلُوٓا۟ أَهْلَ ٱلْكِتَـٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ ۖ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَـٰهُنَا وَإِلَـٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ ﴿46﴾","ref":"العنكبوت: 46","id":"quran:29:46"},{"k":"q","t":"ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَـٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ ﴿125﴾","ref":"النحل: 125","id":"quran:16:125"}]},{"t":"لا تسبوا","d":"","ev":[{"k":"q","t":"وَلَا تَسُبُّوا۟ ٱلَّذِينَ يَدْعُونَ مِن دُونِ ٱللَّهِ فَيَسُبُّوا۟ ٱللَّهَ عَدْوًۢا بِغَيْرِ عِلْمٍ ۗ كَذَٰلِكَ زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمْ ثُمَّ إِلَىٰ رَبِّهِم مَّرْجِعُهُمْ فَيُنَبِّئُهُم بِمَا كَانُوا۟ يَعْمَلُونَ ﴿108﴾","ref":"الأنعام: 108","id":"quran:6:108"}]}]},{"id":"akhlaq","t":"أخلاق النبي ﷺ دليل على صدقه","intro":"صفاته التي شهد بها أعداؤه قبل أتباعه: الصدق، والأمانة، والحلم، والتواضع، والزهد، والوفاء.","points":[{"t":"وإنك لعلى خلق عظيم","d":"","ev":[{"k":"q","t":"وَإِنَّكَ لَعَلَىٰ خُلُقٍ عَظِيمٍ ﴿4﴾","ref":"القلم: 4","id":"quran:68:4"}]},{"t":"صدقه وأمانته","d":"","ev":[{"k":"b","t":"فكان صلى الله عليه وسلم آمن الناس وأعدل الناس وأعف الناس وأصدقهم لهجة منذ كان اعترف بذلك محادوه وعداته وكان يسمى قبل النبوة الأمين وذلك لما جعل الله فيه من الأخلاق الصالحة ومما يدل على ذلك أن قريشا لما بنيت الكعبة اختلفت فيمن يضع الحجر الأسود موضعه فحكموا بينهم أول داخل عليهم فإذا بالنبي محمد صلى الله عليه وسلم داخلا فقالوا هذا محمد هذا الأمين قد رضينا به وذلك قبل أن يبعث ولقد اجتمع الأخنس بن شريق مع أبي جهل يوم بدر وكلاهما مخالف وعدو له قد أجمع على قتله وقتاله فقال الأخنس لأبي جهل يا أبا الحكم ليس هنا غيري وغيرك …","ref":"القرطبي: عدله وصدقه وأمانته","id":"iclam-nasara:147","sec":"وأما عدله وصدقه صلى الله عليه وسلم وأمانته وصدق لهجته"}]},{"t":"حلمه وتواضعه","d":"","ev":[{"k":"b","t":"فيكفيك من ذلك أنه كسرت رباعيته يوم أحد وشج في وجه فشق ذلك على أصحابه فقالوا له لو دعوت الله عليهم فقال إني لم أبعث لعانا وإنما بعثت رحمة ثم قال اللهم اهد قومي فإنهم لا يعلمون فأنظر ما في هذا القول من جماع الفضل ودرجات الإحسان وحسن الخلق وكرم النفس وغاية الصبر والحلم إذ لم يقصر على السكوت عنهم حتى عفى ثم أشفق عليهم ورحمهم ودعا وشفع لهم ثم أظهر سبب الشفقة والرحمة بقوله لقومي ثم اعتذر عنهم لجهلهم فقال فإنهم لا يعلمون وكذلك جاء أعرابي جلف جاف وكان على النبي صلى الله عليه وسلم برد غليظ الحاشية فجذبه الأعرابي بردائيه …","ref":"القرطبي: صبره وحلمه","id":"iclam-nasara:145","sec":"وأما صبره وحلمه"},{"k":"b","t":"صلى الله عليه وسلم على علو منصبه ورفعة رتبته فكان أشد الناس تواضعا وأبعدهم عن كبر وحسبك أن الله خيره بين أن يكون نبيا ملكا أو نبيا عبدا فاختار أن يكون نبيا عبدا فقال له إسرافيل عليه السلام عند ذلك فإن الله قد أعطاك بما تواضعت له أنك سيد ولد آدم يوم القيامة وأول من تنشق الأرض عنه وأول شافع وقال أبو أمامة خرج علينا رسول الله صلى الله عليه وسلم متوكأ على عصا فقمنا له فقال لا تقوموا كما تقوم الأعاجم يعظم بعضها بعضا وقال إنما أنا عبد آكل كما يأكل العبد وأجلس كما يجلس العبد وكان يركب الحمار ويردف خلفه ويعود المساكين …","ref":"القرطبي: تواضعه","id":"iclam-nasara:146","sec":"وأما تواضعه"}]}]},{"id":"muajizat","t":"معجزات النبي ﷺ الحسية","intro":"إلى جانب القرآن، أيّده الله بمعجزات حسية رآها الناس: انشقاق القمر، ونبع الماء من بين أصابعه، وتكثير الطعام.","points":[{"t":"انشقاق القمر","d":"","ev":[{"k":"q","t":"ٱقْتَرَبَتِ ٱلسَّاعَةُ وَٱنشَقَّ ٱلْقَمَرُ ﴿1﴾ وَإِن يَرَوْا۟ ءَايَةً يُعْرِضُوا۟ وَيَقُولُوا۟ سِحْرٌ مُّسْتَمِرٌّ ﴿2﴾","ref":"القمر: 1–2","id":"quran:54:1"},{"k":"b","t":"آية له صلى الله عليه وسلم فنقول نقل خلفنا عن سلفنا النقل الذي لا يشك فيه أن كفار قريش سألوا رسول الله صلى الله عليه وسلم أبة وهو بمنى فأراهم إنشقاق القمر فصار فرقتين حتى رأوا حبلى حراء بينهما وقال ابن مسعود صار فرقتين فرقة فوق الجبل وفرقة تحته فقال النبي صلى الله عليه وسلم اشهدوا فآمن وصدق من أراد الله نجاته وقال كفار قريش هذا سحر مستمر فقال أبو جهل هذا سحر فابعثوا إلى أهل الآفاق حتى ننظر أرأوا ذلك أم لا فأخبر أهل مكة أنهم رأوه منشقا فأنزل الله تعالى على نبيه محمد صلى الله عليه وسلم {اقتربت الساعة وانشق القمر وإن …","ref":"القرطبي: الفصل الأول في انشقاق القمر","id":"iclam-nasara:171","sec":"الفصل الأول في إنشقاق القمر"}]},{"t":"نبع الماء وتكثير الطعام","d":"","ev":[{"k":"b","t":"وهذا الفصل نوعان نوع نبع له الماء من بين أصابعه ونوع آخر نبع له الماء من غير أصابعه فلنبدأ بالأول فنقول روى الجم الغفير والعدد الكثير أن النبي صلى الله عليه وسلم خرج في بعض أسفاره وحانت صلاة العصر فالتمس الناس الوضوء فلم يجدوه فقال رسول الله صلى الله عليه وسلم هل من أحد منكم ماء فأتى بماء في إناء فوضع يده في ذلك الإناء وسمى الله قالت الصحابة فرأينا الماء يخرج من بين أصابعه فتوضأ الناس حتى توضأوا كلهم قيل لأنس كم تراهم قال نحوا من سبعين وقد اتفق له مثل هذا مرة أخرى وكانوا نحوا من ثلاثة مائة وكذلك عطش الناس يوم …","ref":"القرطبي: نبع الماء","id":"iclam-nasara:173","sec":"الفصل الثالث نبع الماء وتكثيره معجزة له صلى الله عليه وسلم"},{"k":"b","t":"من ذلك ما تضافرت به الروايات واشتهر عند أهل الديانات ونقله العدول الثقات من حديث أبي طلحة أن النبي صلى الله عليه وسلم أطم ثمانين أو سبعين من أقراص شعير جاء بها أنس تحت ابطه وذلك أنه صلى الله عليه وسلم أمر بها ففتت وقال فيها ما شاء الله أن يقول وكذلك أطعم يوم الخندق ألف رجل من صاع من شعير وعناق قال جابر بن عبد الله فأقسم بالله لأكلوا حتى تركوه وانحرفوا وإن برمتنا لتغط كما هي وإن عجيننا ليخبز وكان رسول الله صلى الله عليه وسلم بصق في العجين والبرمة ودعا بالبركة وكذلك صنع أبو أيوب الأنصاري لرسول الله صلى الله عليه …","ref":"القرطبي: تكثير الطعام","id":"iclam-nasara:174","sec":"الفصل الرابع تكثير الطعام معجزة له صلى الله عليه وسلم"}]}]},{"id":"shariaa","t":"مقاصد الشريعة: حفظ الضروريات الخمس","intro":"جاءت الشريعة بحفظ الدين والنفس والعقل والنسب والمال؛ وهذا من أعظم دلائل أنها من عند الحكيم العليم.","points":[{"t":"أصول الشريعة","d":"","ev":[{"k":"b","t":"فأما بمرتبة واحدة أو بمراتب على ما يعرف في موضعه","ref":"القرطبي: أصول الشريعة راجعة إلى خمسة","id":"iclam-nasara:139","sec":"فأصول الشريعة وإن تعددت صورها فهي راجعة إلى هذه الخمسة"}]},{"t":"إن الله يأمر بالعدل والإحسان","d":"","ev":[{"k":"q","t":"إِنَّ ٱللَّهَ يَأْمُرُ بِٱلْعَدْلِ وَٱلْإِحْسَـٰنِ وَإِيتَآئِ ذِى ٱلْقُرْبَىٰ وَيَنْهَىٰ عَنِ ٱلْفَحْشَآءِ وَٱلْمُنكَرِ وَٱلْبَغْىِ ۚ يَعِظُكُمْ لَعَلَّكُمْ تَذَكَّرُونَ ﴿90﴾","ref":"النحل: 90","id":"quran:16:90"}]}]}]},{"id":"naqd","ic":"⚖️","name":"بيان أخطاء العقائد الأخرى بالحجة","intro":"نقد علمي هادئ لعقائد النصارى واليهود وغيرهم، بأدلة العقل ونصوص كتبهم، كما بيّنها علماء الإسلام، مع الرحمة بالمخاطب والحرص على هدايته.","topics":[{"id":"uluhiyya","t":"ألوهية المسيح: هل قالها المسيح؟","intro":"المسيح عليه السلام في الأناجيل نفسها يصلي لله ويدعوه، ويقول إن الإله الحقيقي واحد، وينسب إلى الله ما لا يعلمه هو؛ وهذه صفات العبد الرسول لا صفات الإله.","points":[{"t":"من كلام المسيح في الأناجيل","d":"نقل رحمة الله الهندي من إنجيل يوحنا قول المسيح: «أن يعرفوك أنت الإله الحقيقي وحدك ويسوع المسيح الذي أرسلته»، ومن مرقس: «الرب إلهنا رب واحد».","ev":[{"k":"b","t":": في الآية الثالثة من الباب السابع عشر من إنجيل يوحنا قول عيسى عليه السلام في خطاب الله هكذا: (وهذه هي الحياة الأبدية أن يعرفوك أنت الإله الحقيقي وحدك ويسوع المسيح الذي أرسلته) فبين عيسى عليه السلام أن الحياة الأبدية، عبارة عن أن يعرف الناس أن الله واحد حقيقي وأن عيسى عليه السلام رسوله. وما قال إن الحياة الأبدية أن يعرفوا أن ذاتك ثلاثة أقانيم ممتازة بامتياز حقيقي وأن عيسى إنسان وإله، أو أن عيسى إله مجسم ولما كان هذا القول في خطاب الله في الدعاء فلا احتمال ههنا للخوف من اليهود فلو كان اعتقاد التثليث مدار النجاة …","ref":"إظهار الحق: القول الأول","id":"izhar-haqq:459","sec":"القول الأول"},{"k":"b","t":": في الباب الثاني عشر من إنجيل مرقس هكذا 28: (فجاء واحد من الكتبة وسمعهم يتحاورون، فلما رأى أنه أجابهم حسنا سأله: أية وصية هي أول الكل) 29: (فأجابه يسوع أن أول كل الوصايا اسمع يا إسرائيل الرب إلهنا رب واحد. [30] : وتحب الرب إلهك من كل قلبك ومن كل نفسك ومن كل فكرك ومن كل قدرتك هذه هي الوصية الأولى [31] وثانية مثلها هي أن تحب قريبك كنفسك ليس وصية أخرى أعظم من هاتين [32] فقال له الكاتب جيدا يا معلم بالحق قلت لأنه) أي الله (واحد وليس آخر سواه) 33 (ومحبته من كل القلب ومن كل الفهم ومن كل النفس ومن كل القدرة ومحبة القريب …","ref":"إظهار الحق: القول الثاني","id":"izhar-haqq:460","sec":"القول الثاني"}]},{"t":"إما الله وإما رسول الله","d":"حجة ابن تيمية: الذي كلّم الناس إما أن يكون هو الله أو رسول الله، فإن كان الله بطل أن يكون رسولاً، وإن كان رسولاً بطل أن يكون هو الله.","ev":[{"k":"b","t":"وقولهم إنه إله بلاهوته ورسول بناسوته كلام باطل من وجوه. منها أن الذي كان يكلم الناس إما أن يكون هو الله أو هو رسول الله، فإن كان هو الله بطل كونه رسول الله وإن كان رسول الله بطل كونه هو الله. ولهذا لما كان الذي كلم موسى - عليه السلام - من الشجرة هو الله لم تنطق الكتب بأنه رسول الله، وهذا وارد بأي وجه فسروا الاتحاد، فإنه من المعلوم أن الناس كانوا يسمعون من المسيح كلاما بصوته المعروف وصوته لم يختلف ولا حاله عند الكلام تغيرت كما يختلف الإنسان وحاله عند الكلام إذا حل فيه الجني وإذا فارقه الجني، فإن الجني إذا تكلم على …","ref":"ابن تيمية في «الجواب الصحيح»","id":"jawab-sahih:45","sec":"إبطال دعوى النصارى إلهية المسيح عليه السلام"}]},{"t":"مثل عيسى كمثل آدم","d":"","ev":[{"k":"q","t":"إِنَّ مَثَلَ عِيسَىٰ عِندَ ٱللَّهِ كَمَثَلِ ءَادَمَ ۖ خَلَقَهُۥ مِن تُرَابٍ ثُمَّ قَالَ لَهُۥ كُن فَيَكُونُ ﴿59﴾","ref":"آل عمران: 59","id":"quran:3:59"},{"k":"q","t":"إِنْ هُوَ إِلَّا عَبْدٌ أَنْعَمْنَا عَلَيْهِ وَجَعَلْنَـٰهُ مَثَلًا لِّبَنِىٓ إِسْرَٰٓءِيلَ ﴿59﴾","ref":"الزخرف: 59","id":"quran:43:59"},{"k":"q","t":"لَقَدْ كَفَرَ ٱلَّذِينَ قَالُوٓا۟ إِنَّ ٱللَّهَ هُوَ ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ ۖ وَقَالَ ٱلْمَسِيحُ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ ٱعْبُدُوا۟ ٱللَّهَ رَبِّى وَرَبَّكُمْ ۖ إِنَّهُۥ مَن يُشْرِكْ بِٱللَّهِ فَقَدْ حَرَّمَ ٱللَّهُ عَلَيْهِ ٱلْجَنَّةَ وَمَأْوَىٰهُ ٱلنَّارُ ۖ وَمَا لِلظَّـٰلِمِينَ مِنْ أَنصَارٍ ﴿72﴾","ref":"المائدة: 72","id":"quran:5:72"}]}]},{"id":"tathlith2","t":"التثليث في ميزان العقل","intro":"يقول النصارى: ثلاثة أقانيم وإله واحد؛ والعقل يقضي بأن الكثرة الحقيقية تنافي الوحدة الحقيقية، فلا يجتمعان إلا بالتناقض، ولو تميّزت الأقانيم حقيقة لكان الإله مركّباً، والمركّب مفتقر إلى أجزائه، والمفتقر لا يكون إلهاً.","points":[{"t":"البرهان الأول: اجتماع الضدين","d":"","ev":[{"k":"b","t":"لما كان التثليث والتوحيد حقيقيين عند المسيحيين بحكم الأمر العاشر من المقدمة فإذا وجد التثليث الحقيقي لا بد من أن توجد الكثرة الحقيقية أيضا بحكم الأمر التاسع من المقدمة ولا يمكن بعد ثبوتها التوحيد الحقيقي وإلا يلزم اجتماع الضدين الحقيقيين بحكم الأمر السابع من المقدمة وهو محال، فلزم تعدد الوجباء وفات التوحيد يقينا. فقائل التثليث لا يمكن أن يكون موحدا لله تعالى بالتوحيد الحقيقي، والقول بأن التثليث الحقيقي والتوحيد الحقيقي وإن كانا ضدين حقيقين في غير الواجب لكنهما ما ليسا كذلك، فيه سفسطة محضة لأنه إذا ثبت أن الشيئين …","ref":"إظهار الحق: البرهان الأول","id":"izhar-haqq:451","sec":"البرهان الأول"}]},{"t":"البرهان الثاني: لزوم التركيب","d":"","ev":[{"k":"b","t":"لو وجد في ذات الله ثلاثة أقانيم ممتازة بامتياز حقيقي كما قالوا فمع قطع النظر عن تعدد الوجباء يلزم أن لا يكون الله حقيقة محصلة بل مركبا اعتباريا فإن التركيب الحقيقي لا بد فيه من الافتقار بين الأجزاء، فإن الحجر الموضوع يجنب الإنسان لا يحصل منهما أحدية، ولا افتقار بين الواجبات، لأنه من خواص الممكنات، فالواجب لا يفتقر إلى الغير وكل جزء منفصل عن الآخر وغيره وإن كان داخلا في المجموع، فإذا لم يفتقر بعض الأجزاء إلى بعض آخر لم تتألف منها الذات الأحدية، على أنه يكون الله في الصورة المذكورة مركبا، وكل مركب يفتقر في تحققه إلى …","ref":"إظهار الحق: البرهان الثاني","id":"izhar-haqq:452","sec":"البرهان الثاني"}]},{"t":"ولا تقولوا ثلاثة","d":"","ev":[{"k":"q","t":"يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ ۖ سُبْحَـٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ ۘ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿171﴾","ref":"النساء: 171","id":"quran:4:171"},{"k":"q","t":"قُلْ هُوَ ٱللَّهُ أَحَدٌ ﴿1﴾ ٱللَّهُ ٱلصَّمَدُ ﴿2﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿3﴾ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ ﴿4﴾","ref":"الإخلاص: 1–4","id":"quran:112:1"}]}]},{"id":"ittihad","t":"الحلول والاتحاد: «الكلمة صارت جسداً»","intro":"دعوى أن كلمة الله اتحدت بجسد المسيح تناقض العقل: فالخالق لا يحلّ في المخلوق، والكلمة صفة لا تنفصل عن الموصوف، والجسد كان يأكل وينام ويتألم.","points":[{"t":"ردّ ابن تيمية","d":"","ev":[{"k":"b","t":"وأما قولهم: فكان طيرا بإذن الله أي بإذن اللاهوت الذي هو كلمة الله المتحدة في الناسوت فهذا إذا قالوه على أنه مذهبهم من غير أن يقولوا أن محمدا أراده تكلمنا معهم في ذلك وبينا فساد ذلك عقلا ونقلا. وأما قولهم: أن محمدا - صلى الله عليه وسلم - كان يقول: أن المراد إذن اللاهوت الذي هو كلمة الله المتحدة في الناسوت فهذا من البهتان الظاهر على محمد - صلى الله عليه وسلم - وهو من جنس قولهم أن قوله: {اهدنا الصراط المستقيم صراط الذين أنعمت عليهم} [الفاتحة: 6] أراد به النصارى ومن جنس قولهم أن قوله: {ومن يبتغ غير الإسلام دينا} [آل …","ref":"ابن تيمية: إبطال دعوى الاتحاد","id":"jawab-sahih:57","sec":"فصل: إبطال دعواهم اتحاد كلمة الله بجسد المسيح"}]},{"t":"كانا يأكلان الطعام","d":"","ev":[{"k":"q","t":"مَّا ٱلْمَسِيحُ ٱبْنُ مَرْيَمَ إِلَّا رَسُولٌ قَدْ خَلَتْ مِن قَبْلِهِ ٱلرُّسُلُ وَأُمُّهُۥ صِدِّيقَةٌ ۖ كَانَا يَأْكُلَانِ ٱلطَّعَامَ ۗ ٱنظُرْ كَيْفَ نُبَيِّنُ لَهُمُ ٱلْـَٔايَـٰتِ ثُمَّ ٱنظُرْ أَنَّىٰ يُؤْفَكُونَ ﴿75﴾","ref":"المائدة: 75","id":"quran:5:75"}]}]},{"id":"ruh","t":"الروح القدس: من هو؟","intro":"الروح القدس في القرآن هو جبريل عليه السلام، الذي أيّد الله به الأنبياء، وليس إلهاً ثالثاً.","points":[{"t":"نزّله روح القدس","d":"","ev":[{"k":"q","t":"قُلْ نَزَّلَهُۥ رُوحُ ٱلْقُدُسِ مِن رَّبِّكَ بِٱلْحَقِّ لِيُثَبِّتَ ٱلَّذِينَ ءَامَنُوا۟ وَهُدًى وَبُشْرَىٰ لِلْمُسْلِمِينَ ﴿102﴾","ref":"النحل: 102","id":"quran:16:102"},{"k":"q","t":"وَلَقَدْ ءَاتَيْنَا مُوسَى ٱلْكِتَـٰبَ وَقَفَّيْنَا مِنۢ بَعْدِهِۦ بِٱلرُّسُلِ ۖ وَءَاتَيْنَا عِيسَى ٱبْنَ مَرْيَمَ ٱلْبَيِّنَـٰتِ وَأَيَّدْنَـٰهُ بِرُوحِ ٱلْقُدُسِ ۗ أَفَكُلَّمَا جَآءَكُمْ رَسُولٌۢ بِمَا لَا تَهْوَىٰٓ أَنفُسُكُمُ ٱسْتَكْبَرْتُمْ فَفَرِيقًا كَذَّبْتُمْ وَفَرِيقًا تَقْتُلُونَ ﴿87﴾","ref":"البقرة: 87","id":"quran:2:87"}]},{"t":"ردّ ابن تيمية","d":"","ev":[{"k":"b","t":"وأما قوله - تعالى -: {وآتينا عيسى ابن مريم البينات وأيدناه بروح القدس} [البقرة: 87] فهو حق كما أخبر الله به وقد ذكر تعالى تأييد عيسى ابن مريم بروح القدس في عدة مواضع فقال - تعالى - في سورة البقرة {ولقد آتينا موسى الكتاب وقفينا من بعده بالرسل وآتينا عيسى ابن مريم البينات وأيدناه بروح القدس} [البقرة: 87] وقال - تعالى -: {تلك الرسل فضلنا بعضهم على بعض منهم من كلم الله ورفع بعضهم درجات وآتينا عيسى ابن مريم البينات وأيدناه بروح القدس ولو شاء الله ما اقتتل الذين من بعدهم من بعد ما جاءتهم البينات ولكن اختلفوا فمنهم من …","ref":"ابن تيمية: معنى روح القدس","id":"jawab-sahih:59","sec":"فصل: بيان معنى الروح القدس ودفع اعتقاد النصارى ألوهيته"}]}]},{"id":"fida","t":"الخطيئة الموروثة والفداء","intro":"عقيدة أن البشر ورثوا خطيئة آدم فلا تُغفر إلا بصلب المسيح، تخالف العدل والرحمة: فآدم تاب فتاب الله عليه، ولا يحمل أحد ذنب غيره، والله يغفر لمن تاب بلا فداء.","points":[{"t":"آدم تاب فتاب الله عليه","d":"","ev":[{"k":"q","t":"فَتَلَقَّىٰٓ ءَادَمُ مِن رَّبِّهِۦ كَلِمَـٰتٍ فَتَابَ عَلَيْهِ ۚ إِنَّهُۥ هُوَ ٱلتَّوَّابُ ٱلرَّحِيمُ ﴿37﴾","ref":"البقرة: 37","id":"quran:2:37"},{"k":"q","t":"فَأَكَلَا مِنْهَا فَبَدَتْ لَهُمَا سَوْءَٰتُهُمَا وَطَفِقَا يَخْصِفَانِ عَلَيْهِمَا مِن وَرَقِ ٱلْجَنَّةِ ۚ وَعَصَىٰٓ ءَادَمُ رَبَّهُۥ فَغَوَىٰ ﴿121﴾ ثُمَّ ٱجْتَبَـٰهُ رَبُّهُۥ فَتَابَ عَلَيْهِ وَهَدَىٰ ﴿122﴾","ref":"طه: 121–122","id":"quran:20:121"}]},{"t":"العدل الإلهي","d":"","ev":[{"k":"q","t":"وَلَا تَزِرُ وَازِرَةٌ وِزْرَ أُخْرَىٰ ۚ وَإِن تَدْعُ مُثْقَلَةٌ إِلَىٰ حِمْلِهَا لَا يُحْمَلْ مِنْهُ شَىْءٌ وَلَوْ كَانَ ذَا قُرْبَىٰٓ ۗ إِنَّمَا تُنذِرُ ٱلَّذِينَ يَخْشَوْنَ رَبَّهُم بِٱلْغَيْبِ وَأَقَامُوا۟ ٱلصَّلَوٰةَ ۚ وَمَن تَزَكَّىٰ فَإِنَّمَا يَتَزَكَّىٰ لِنَفْسِهِۦ ۚ وَإِلَى ٱللَّهِ ٱلْمَصِيرُ ﴿18﴾","ref":"فاطر: 18","id":"quran:35:18"}]},{"t":"حجة ابن تيمية","d":"إبراهيم كان أبوه كافراً ولم يؤاخذه الله بذنب أبيه، فكيف يؤاخذ الناس بذنب أبيهم الأبعد آدم وقد تاب؟","ev":[{"k":"b","t":"ومعلوم أن إبراهيم كان أبوه كافرا ولم يؤاخذه الله بذنب أبيه فكيف يؤاخذه بذنب آدم وهو أبوه الأبعد، هذا لو قدر أن آدم لم يتب فكيف وقد أخبر الله عنه بالتوبة؟ ثم يزعمون أن الصلب الذي هو من أعظم الذنوب والخطايا به خلص الله آدم وذريته من عذاب الجحيم وبه عاقب إبليس مع أن إبليس ما زال عاصيا لله مستحقا للعقاب من حين امتنع من السجود لآدم ووسوس لآدم إلى حين مبعث المسيح والرب قادر على عقوبته وبنو آدم لا عقوبة عليهم في ذنب أبيهم فمن كان قولهم مثل هذه الخرافات التي هي مضاحك العقلاء والتي لا تصلح أن تضاف إلى أجهل الملوك وأظلمهم …","ref":"ابن تيمية: رد عقيدة الصلب والفداء","id":"jawab-sahih:52","sec":"فصل: رد عقيدة النصارى في الصلب والفداء"}]}]},{"id":"sanad","t":"الأناجيل: من كتبها؟ وما سندها؟","intro":"الكتاب الإلهي يجب أن يثبت أنه كُتب بواسطة نبي، ثم وصل إلينا بسند متصل بلا تغيير. وأهل الكتاب لا يملكون سنداً متصلاً لكتبهم، بخلاف القرآن المنقول بالتواتر حفظاً وكتابة.","points":[{"t":"لا سند متصل لكتبهم","d":"","ev":[{"k":"b","t":"اعلم أرشدك الله تعالى أنه لا بد لكون الكتاب سماويا واجب التسليم أن يثبت أولا بدليل تام أن هذا الكتاب كتب بواسطة النبي الفلاني ووصل بعد ذلك إلينا بالسند المتصل بلا تغيير ولا تبديل، والاستناد إلى شخص ذي إلهام بمجرد الظن والوهم لا يكفي في إثبات أنه من تصنيف ذلك الشخص، وكذلك مجرد ادعاء فرقة أو فرق لا يكفي فيه، ألا ترى أن كتاب المشاهدات والسفر الصغير للتكوين، وكتاب المعراج، وكتاب الأسرار، وكتاب تستمنت، وكتاب الإقرار منسوبة إلى موسى عليه السلام، وكذلك السفر الرابع لعزرا منسوب إلى عزرا، وكتاب معراج أشعيا، وكتاب مشاهدات …","ref":"إظهار الحق: الفصل الثاني","id":"izhar-haqq:21","sec":"الفصل الثاني: في بيان أن أهل الكتاب لا يوجد عندهم سند متصل لكتاب من كتب العهد العتيق والجديد."}]},{"t":"القرآن المحفوظ","d":"","ev":[{"k":"q","t":"إِنَّا نَحْنُ نَزَّلْنَا ٱلذِّكْرَ وَإِنَّا لَهُۥ لَحَـٰفِظُونَ ﴿9﴾","ref":"الحجر: 9","id":"quran:15:9"},{"k":"q","t":"لَّا يَأْتِيهِ ٱلْبَـٰطِلُ مِنۢ بَيْنِ يَدَيْهِ وَلَا مِنْ خَلْفِهِۦ ۖ تَنزِيلٌ مِّنْ حَكِيمٍ حَمِيدٍ ﴿42﴾","ref":"فصلت: 42","id":"quran:41:42"}]}]},{"id":"ikhtilaf","t":"الاختلاف والأغلاط في الكتب الموجودة","intro":"وجد العلماء في الكتب المتداولة اختلافات كثيرة بين نصوصها في الأعداد والأسماء والأحداث، وهذا من علامات وقوع التغيير فيها، أما القرآن فلا اختلاف فيه.","points":[{"t":"لو كان من عند غير الله","d":"","ev":[{"k":"q","t":"أَفَلَا يَتَدَبَّرُونَ ٱلْقُرْءَانَ ۚ وَلَوْ كَانَ مِنْ عِندِ غَيْرِ ٱللَّهِ لَوَجَدُوا۟ فِيهِ ٱخْتِلَـٰفًا كَثِيرًا ﴿82﴾","ref":"النساء: 82","id":"quran:4:82"}]},{"t":"أمثلة الاختلاف في «إظهار الحق»","d":"جمع رحمة الله الهندي أكثر من مائة موضع من الاختلاف والغلط، بالإحالة إلى أسفارهم وإصحاحاتهم.","ev":[{"k":"b","t":"[1] الأول من قابل الباب الخامس والأربعين والسادس والأربعين من كتاب حزقيال بالباب الثامن والعشرين والتاسع والعشرين من سفر العدد وجد اختلافا صريحا في الأحكام","ref":"إظهار الحق: الاختلاف (أمثلة)","id":"izhar-haqq:60","sec":"الأختلاف"},{"k":"b","t":"[1] وقع في الآية الأربعين من الباب الثاني عشر من سفر الخروج أن مدة إقامة بني إسرائيل في مصر كانت أربعمائة وثلاثين سنة، وهذا غلط، لأن هذه المدة مائتان وخمس عشرة سنة، وقد أقر مفسروهم ومؤرخوهم أيضا أنه غلط كما ستعرف في الشاهد الأول من المقصد الثالث من الباب الثاني.","ref":"إظهار الحق: القسم الثاني في الأغلاط","id":"izhar-haqq:170","sec":"الغلط"}]}]},{"id":"tahrif2","t":"إثبات التحريف","intro":"التحريف نوعان: تحريف المعنى بالتأويل الباطل، وتحريف اللفظ بالتبديل والزيادة والنقص. والأول يقرّ به النصارى على اليهود، والثاني أثبته العلماء بشواهد كثيرة.","points":[{"t":"يحرفون الكلم","d":"","ev":[{"k":"q","t":"فَبِمَا نَقْضِهِم مِّيثَـٰقَهُمْ لَعَنَّـٰهُمْ وَجَعَلْنَا قُلُوبَهُمْ قَـٰسِيَةً ۖ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ ۙ وَنَسُوا۟ حَظًّا مِّمَّا ذُكِّرُوا۟ بِهِۦ ۚ وَلَا تَزَالُ تَطَّلِعُ عَلَىٰ خَآئِنَةٍ مِّنْهُمْ إِلَّا قَلِيلًا مِّنْهُمْ ۖ فَٱعْفُ عَنْهُمْ وَٱصْفَحْ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُحْسِنِينَ ﴿13﴾","ref":"المائدة: 13","id":"quran:5:13"},{"k":"q","t":"مِّنَ ٱلَّذِينَ هَادُوا۟ يُحَرِّفُونَ ٱلْكَلِمَ عَن مَّوَاضِعِهِۦ وَيَقُولُونَ سَمِعْنَا وَعَصَيْنَا وَٱسْمَعْ غَيْرَ مُسْمَعٍ وَرَٰعِنَا لَيًّۢا بِأَلْسِنَتِهِمْ وَطَعْنًا فِى ٱلدِّينِ ۚ وَلَوْ أَنَّهُمْ قَالُوا۟ سَمِعْنَا وَأَطَعْنَا وَٱسْمَعْ وَٱنظُرْنَا لَكَانَ خَيْرًا لَّهُمْ وَأَقْوَمَ وَلَـٰكِن لَّعَنَهُمُ ٱللَّهُ بِكُفْرِهِمْ فَلَا يُؤْمِنُونَ إِلَّا قَلِيلًا ﴿46﴾","ref":"النساء: 46","id":"quran:4:46"}]},{"t":"إظهار الحق: إثبات التحريف","d":"","ev":[{"k":"b","t":"وهو قسمان لفظي ومعنوي، ولا نزاع بيننا وبين المسيحيين في القسم الثاني لأنهم يسلمون كلهم صدوره عن اليهود في العهد العتيق في تفسير الآيات، التي هي إشارة في زعمهم إلى المسيح، وفي تفسير الأحكام التي هي أبدية عند اليهود، وأن علماء البروتستنت يعترفون بصدوره عن معتقدي البابا في كتب العهدين، كما أن معتقدي البابا يرمونهم بهذا رميا شديدا فلا احتياج إلى إثباته. بقي القسم الأول، وقد أنكره علماء البروتستنت في الظاهر إنكارا بليغا لتغليط جهال المسلمين وأوردوا أدلة مموهة مزورة في رسائلهم ليوقعوا الناظرين في الشك فهو محتاج إلى …","ref":"إظهار الحق: الباب الثاني","id":"izhar-haqq:278","sec":"الباب الثاني: في إثبات التحريف"}]},{"t":"السموأل: سبب تبديل التوراة","d":"السموأل كان من أحبار اليهود ثم أسلم، ويذكر من داخل علمهم كيف لم تبق التوراة المنزلة كما هي.","ev":[{"k":"b","t":"علماؤهم وأحبارهم يعلمون أن هذه التوراة التي بأيديهم لا يعتقد أحد من علمائهم وأحبارهم أنها المنزلة على موسى البتة لأن موسى صان التوراة عن بني إسرائيل ولم يبثها فيهم وإنما سلمها إلى عشيرته أولاد ليوى ودليل ذلك قول التوراة ويختوب موشى إث هتورا هزوت وبيتناه ال هكوا هنيم بنى ليوى تفسيره وكتب موسى هذه التوراة ودفعها إلى الأئمة بني ليوى وكان بنو هارون قضاة اليهود وحكامهم لأن الإمامة وخدمة القرابين وبيت المقدس كانت موقوفة عليهم ولم يبذل موسى من التوراة لبنى إسرائيل إلا نصف سورة يقال لها هاأزينو فإن هذه السورة من التوراة …","ref":"بذل المجهود: ذكر السبب في تبديل التوراة","id":"ifham-yahud:19","sec":"ذكر السبب في تبديل التوراة"}]}]},{"id":"risala","t":"المسيح رسول إلى بني إسرائيل","intro":"المسيح عليه السلام أُرسل إلى بني إسرائيل خاصة، ولم يأمر بنسخ شريعة موسى؛ ثم جاء التغيير بعده: ترك الختان، واستحلال الخنزير، وتعميم الدعوة، بقرارات من بعده.","points":[{"t":"رسولاً إلى بني إسرائيل","d":"","ev":[{"k":"q","t":"وَرَسُولًا إِلَىٰ بَنِىٓ إِسْرَٰٓءِيلَ أَنِّى قَدْ جِئْتُكُم بِـَٔايَةٍ مِّن رَّبِّكُمْ ۖ أَنِّىٓ أَخْلُقُ لَكُم مِّنَ ٱلطِّينِ كَهَيْـَٔةِ ٱلطَّيْرِ فَأَنفُخُ فِيهِ فَيَكُونُ طَيْرًۢا بِإِذْنِ ٱللَّهِ ۖ وَأُبْرِئُ ٱلْأَكْمَهَ وَٱلْأَبْرَصَ وَأُحْىِ ٱلْمَوْتَىٰ بِإِذْنِ ٱللَّهِ ۖ وَأُنَبِّئُكُم بِمَا تَأْكُلُونَ وَمَا تَدَّخِرُونَ فِى بُيُوتِكُمْ ۚ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لَّكُمْ إِن كُنتُم مُّؤْمِنِينَ ﴿49﴾","ref":"آل عمران: 49","id":"quran:3:49"},{"k":"q","t":"وَإِذْ قَالَ عِيسَى ٱبْنُ مَرْيَمَ يَـٰبَنِىٓ إِسْرَٰٓءِيلَ إِنِّى رَسُولُ ٱللَّهِ إِلَيْكُم مُّصَدِّقًا لِّمَا بَيْنَ يَدَىَّ مِنَ ٱلتَّوْرَىٰةِ وَمُبَشِّرًۢا بِرَسُولٍ يَأْتِى مِنۢ بَعْدِى ٱسْمُهُۥٓ أَحْمَدُ ۖ فَلَمَّا جَآءَهُم بِٱلْبَيِّنَـٰتِ قَالُوا۟ هَـٰذَا سِحْرٌ مُّبِينٌ ﴿6﴾","ref":"الصف: 6","id":"quran:61:6"}]},{"t":"ترك الختان بعد المسيح","d":"المسيح كان مختوناً، والختان ثابت في التوراة، ثم تركه أتباعه من بعده.","ev":[{"k":"b","t":"لا خلاف بينهم أن عيسى عليه السلام كان مختونا وأن الختان من أحكام التوراة وثابت فيها وإن أنكر ذلك متواقح جاهل ذكرنا له نص التوراة قال في التوراة إذ حبلت امرأة وولدت ذكرا تكون نجسة سبعة أيام كما تكون أيام حيضتها وفي اليوم الثامن يختن الصبي ونكون نجسة تجلس مكانها ثلاثة وثلاثين يوما وهذا نص لا إشكال فيه ثم إن النصارى بتحكمهم وإستهانتهم بالشرائع تركوا العمل وذلك من غير أصل يعتمدون عليه ولانسخ يثبت عندهم له ومن ادعى منهم شيئا من ذلك طالبناه بنص من الإنجيل وليس لذلك من سبيل غير التحكم بالقال والقيل وقد وجدت في كتبهم …","ref":"القرطبي: مسألة في تركهم الختان","id":"iclam-nasara:220","sec":"مسألة في تركهم الختان"}]},{"t":"ما أحدثوه في الدين","d":"","ev":[{"k":"b","t":"فهذه الدلائل وأضعافها مما تبين أنه نفسه صلى الله عليه وسلم أخبر أنه رسول الله إلى النصارى وغيرهم من أهل الكتاب، وأنه دعاهم وجاهدهم وأمر بدعوتهم وجهادهم، وليس هذا مما فعلته أمته بعده بدعة ابتدعوها، كما فعلت النصارى بعد المسيح عليه السلام، فإن المسلمين لا يجوزون لأحد بعد محمد صلى الله عليه وسلم أن يغيروا شيئا من شريعته، فلا يحلل ما حرم ولا يحرم ما حلل، ولا يوجب ما أسقط ولا يسقط ما أوجب، بل الحلال عندهم ما حلله الله ورسوله، والحرام ما حرم الله ورسوله، والدين ما شرعه الله ورسوله، بخلاف النصارى الذين ابتدعوا بعد المسيح …","ref":"ابن تيمية: ابتداع اليهود والنصارى في دينهم","id":"jawab-sahih:32","sec":"فصل: ابتداع اليهود والنصارى في دينهم"}]}]},{"id":"naskh","t":"اليهود ومسألة النسخ","intro":"يرفض كثير من اليهود أن تأتي شريعة بعد التوراة، مع أن التوراة نفسها فيها شرائع لنوح وإبراهيم تغيّرت بعدهم؛ فالنسخ ثابت في كتابهم، وهو تغيير حكم بحكم لحكمة لا يُعجز الله.","points":[{"t":"ما ننسخ من آية","d":"","ev":[{"k":"q","t":"مَا نَنسَخْ مِنْ ءَايَةٍ أَوْ نُنسِهَا نَأْتِ بِخَيْرٍ مِّنْهَآ أَوْ مِثْلِهَآ ۗ أَلَمْ تَعْلَمْ أَنَّ ٱللَّهَ عَلَىٰ كُلِّ شَىْءٍ قَدِيرٌ ﴿106﴾","ref":"البقرة: 106","id":"quran:2:106"}]},{"t":"إلزامهم النسخ من التوراة","d":"","ev":[{"k":"b","t":"وهذا أول ما أبتدى به من إلزامهم النسخ من نص كتابهم وما تقتضيه أصولهم نقول لهم هل كان قبل نزول التوراة شرع أم لا فإن جحدوا كذبوا بما نطق به الجزء الثاني من السفر الأول من التوراة إذ شرع الله تعالى على نوح عليه السلام القصاص في القتل ذلك قوله شوفيخ دام هاأدام دامو يشافيخ كي بصلم ألوهيم عاما إث هاأدام تفسيره سافك دم الإنسان فليحكم بسفك دمه لأن الله تعالى خلق الآدمي بصورة شريفة وبما يشهد به الجزء الثالث من السفر الأول من التوراة إذ شرع الله على إبراهيم عليه السلام ختانة المولود في اليوم الثامن من ميلاده وهذه وأمثالها …","ref":"السموأل: فصل في إلزامهم النسخ بنص كتابهم","id":"ifham-yahud:6","sec":"فصل في إلزامهم النسخ بنص كتابهم"},{"k":"b","t":"النسخ في اللغة الإزالة، وفي اصطلاح أهل الإسلام بيان مدة انتهاء الحكم العملي الجامع للشروط لأن النسخ لا يطرأ عندنا على القصص ولا على الأمور القطعية العقلية مثل أن صانع العالم موجود، ولا على الأمور الحسية مثل ضوء النهار وظلمة الليل، ولا على الأدعية، ولا على الأحكام التي تكون واجبة نظرا إلى ذاتها مثل آمنوا ولا تشركوا، ولا على الأحكام المؤبدة مثل {ولا تقبلوا لهم شهادة أبدا} ولا على الأحكام المؤقتة قبل وقتها المعين مثل {فاعفوا واصفحوا حتى يأتي الله بأمره} . بل يطرأ على الأحكام التي تكون عملية محتملة للوجود والعدم غير …","ref":"إظهار الحق: الباب الثالث في إثبات النسخ","id":"izhar-haqq:399","sec":"الباب الثالث: في إثبات النسخ."}]}]},{"id":"nubuwwat","t":"إنكار نبوة المسيح ومحمد عليهما السلام","intro":"التوراة تبشّر بمن يأتي بعد موسى، وزوال الملك عن يهوذا بمجيء المسيح، ثم البشارة بنبي من ولد إسماعيل؛ وقد تحققت.","points":[{"t":"كفروا بما عرفوا","d":"","ev":[{"k":"q","t":"وَلَمَّا جَآءَهُمْ كِتَـٰبٌ مِّنْ عِندِ ٱللَّهِ مُصَدِّقٌ لِّمَا مَعَهُمْ وَكَانُوا۟ مِن قَبْلُ يَسْتَفْتِحُونَ عَلَى ٱلَّذِينَ كَفَرُوا۟ فَلَمَّا جَآءَهُم مَّا عَرَفُوا۟ كَفَرُوا۟ بِهِۦ ۚ فَلَعْنَةُ ٱللَّهِ عَلَى ٱلْكَـٰفِرِينَ ﴿89﴾","ref":"البقرة: 89","id":"quran:2:89"},{"k":"q","t":"ٱلَّذِينَ ءَاتَيْنَـٰهُمُ ٱلْكِتَـٰبَ يَعْرِفُونَهُۥ كَمَا يَعْرِفُونَ أَبْنَآءَهُمْ ۖ وَإِنَّ فَرِيقًا مِّنْهُمْ لَيَكْتُمُونَ ٱلْحَقَّ وَهُمْ يَعْلَمُونَ ﴿146﴾","ref":"البقرة: 146","id":"quran:2:146"}]},{"t":"إلزامهم نبوة المسيح","d":"","ev":[{"k":"b","t":"نقول لهم أليس في التوراة التي في أيديكم لو ياسور شبيط ميهودا ومحط قيومبين رغلاف تفسيره لا يزول الملك من آل يهوذا والراسم بين ظهرانيهم إلى إن يأتي المسيح ولا يقدرون على جحده فنقول لهم أفما علمتم أنكم كنت أصحاب دولة وملك إلى ظهور المسيح عليه السلام ثم انقضى ملككم فإن لم يكن لكم اليوم ملك فقد لزمكم من التوراة أن المسيح قد أرسل وأيضا فإنا نقول لهم أليس منذ بعث المسيح عليه السلام استولت ملوك الروم على اليهود وبيت المقدس وانقضت دولتهم وتفرق شملهم فلا يقدرون على جحد ذلك إل بالبهتان ويلزمهم على أصلهم الذي في التوراة أن …","ref":"السموأل: إلزامهم نبوة المسيح","id":"ifham-yahud:11","sec":"إلزامهم نبوة المسيح صلى الله عليه وسلم"}]}]},{"id":"ikhtiyar","t":"دعوى الشعب المختار وأحباء الله","intro":"الكرامة عند الله بالتقوى والعمل لا بالنسب؛ وقد ناقش السموأل دعوى أن الله يحبهم دون الناس بأن من أنبيائهم المقرّ بهم من ليس من نسلهم كأيوب عليه السلام.","points":[{"t":"نحن أبناء الله وأحباؤه","d":"","ev":[{"k":"q","t":"وَقَالَتِ ٱلْيَهُودُ وَٱلنَّصَـٰرَىٰ نَحْنُ أَبْنَـٰٓؤُا۟ ٱللَّهِ وَأَحِبَّـٰٓؤُهُۥ ۚ قُلْ فَلِمَ يُعَذِّبُكُم بِذُنُوبِكُم ۖ بَلْ أَنتُم بَشَرٌ مِّمَّنْ خَلَقَ ۚ يَغْفِرُ لِمَن يَشَآءُ وَيُعَذِّبُ مَن يَشَآءُ ۚ وَلِلَّهِ مُلْكُ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَمَا بَيْنَهُمَا ۖ وَإِلَيْهِ ٱلْمَصِيرُ ﴿18﴾","ref":"المائدة: 18","id":"quran:5:18"},{"k":"q","t":"قُلْ يَـٰٓأَيُّهَا ٱلَّذِينَ هَادُوٓا۟ إِن زَعَمْتُمْ أَنَّكُمْ أَوْلِيَآءُ لِلَّهِ مِن دُونِ ٱلنَّاسِ فَتَمَنَّوُا۟ ٱلْمَوْتَ إِن كُنتُمْ صَـٰدِقِينَ ﴿6﴾","ref":"الجمعة: 6","id":"quran:62:6"}]},{"t":"إن أكرمكم عند الله أتقاكم","d":"","ev":[{"k":"q","t":"يَـٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقْنَـٰكُم مِّن ذَكَرٍ وَأُنثَىٰ وَجَعَلْنَـٰكُمْ شُعُوبًا وَقَبَآئِلَ لِتَعَارَفُوٓا۟ ۚ إِنَّ أَكْرَمَكُمْ عِندَ ٱللَّهِ أَتْقَىٰكُمْ ۚ إِنَّ ٱللَّهَ عَلِيمٌ خَبِيرٌ ﴿13﴾","ref":"الحجرات: 13","id":"quran:49:13"}]},{"t":"مناظرة السموأل","d":"","ev":[{"k":"b","t":"هم يزعمون أن الله سبحانه وتعالى يحبهم دون جميع الناس ويحب طائفتهم وسلالتهم وأن الأنبياء والصالحين لا يختارهم الله إلا منهم ونحن نناظرهم على ذلك فنقول لهم ما قولكم في أيوب النبي عليه السلام أتقرون بنبوته فيقولون نعم فنقول لهم هل هو من بني إسرائيل فيقولون لا فنقول لهم ما تقولون في جمهور بني إسرائيل أعنى التسعة أسباط والنصف الذين أغواهم يربعام بن نباط الذي خرج على ولد سليمان بن داوود عليهما السلام وصنع لهم الكبشين من الذهب وعكف على عبادتهما جماعة بني إسرائيل وأهل جميع ولاية دار ملكهم الملقبة يومئذ بشومرون إلى أن جرت …","ref":"بذل المجهود: فصل في إبطال ما يدعونه من محبة الله إياهم","id":"ifham-yahud:17","sec":"فصل في إبطال ما يدعونه من محبة الله إياهم"}]}]},{"id":"wasat","t":"الإسلام وسط بين تفريط اليهود وغلو النصارى","intro":"اليهود قصّروا في حق الأنبياء فكذبوا بعضهم وقتلوا بعضهم، والنصارى غلوا فيهم حتى جعلوهم آلهة؛ والإسلام وسط: الأنبياء عباد مكرمون نؤمن بهم جميعاً.","points":[{"t":"أمة وسطاً","d":"","ev":[{"k":"q","t":"وَكَذَٰلِكَ جَعَلْنَـٰكُمْ أُمَّةً وَسَطًا لِّتَكُونُوا۟ شُهَدَآءَ عَلَى ٱلنَّاسِ وَيَكُونَ ٱلرَّسُولُ عَلَيْكُمْ شَهِيدًا ۗ وَمَا جَعَلْنَا ٱلْقِبْلَةَ ٱلَّتِى كُنتَ عَلَيْهَآ إِلَّا لِنَعْلَمَ مَن يَتَّبِعُ ٱلرَّسُولَ مِمَّن يَنقَلِبُ عَلَىٰ عَقِبَيْهِ ۚ وَإِن كَانَتْ لَكَبِيرَةً إِلَّا عَلَى ٱلَّذِينَ هَدَى ٱللَّهُ ۗ وَمَا كَانَ ٱللَّهُ لِيُضِيعَ إِيمَـٰنَكُمْ ۚ إِنَّ ٱللَّهَ بِٱلنَّاسِ لَرَءُوفٌ رَّحِيمٌ ﴿143﴾","ref":"البقرة: 143","id":"quran:2:143"},{"k":"q","t":"يَـٰٓأَهْلَ ٱلْكِتَـٰبِ لَا تَغْلُوا۟ فِى دِينِكُمْ وَلَا تَقُولُوا۟ عَلَى ٱللَّهِ إِلَّا ٱلْحَقَّ ۚ إِنَّمَا ٱلْمَسِيحُ عِيسَى ٱبْنُ مَرْيَمَ رَسُولُ ٱللَّهِ وَكَلِمَتُهُۥٓ أَلْقَىٰهَآ إِلَىٰ مَرْيَمَ وَرُوحٌ مِّنْهُ ۖ فَـَٔامِنُوا۟ بِٱللَّهِ وَرُسُلِهِۦ ۖ وَلَا تَقُولُوا۟ ثَلَـٰثَةٌ ۚ ٱنتَهُوا۟ خَيْرًا لَّكُمْ ۚ إِنَّمَا ٱللَّهُ إِلَـٰهٌ وَٰحِدٌ ۖ سُبْحَـٰنَهُۥٓ أَن يَكُونَ لَهُۥ وَلَدٌ ۘ لَّهُۥ مَا فِى ٱلسَّمَـٰوَٰتِ وَمَا فِى ٱلْأَرْضِ ۗ وَكَفَىٰ بِٱللَّهِ وَكِيلًا ﴿171﴾","ref":"النساء: 171","id":"quran:4:171"}]},{"t":"ابن تيمية: توسط المسلمين","d":"","ev":[{"k":"b","t":"قولهم ثم وجدنا في هذا الكتاب من تعظيم السيد المسيح وأمه حيث يقول في سورة الأنبياء {والتي أحصنت فرجها فنفخنا فيها من روحنا وجعلناها وابنها آية للعالمين} [الأنبياء: 91] وقال في سورة آل عمران {وإذ قالت الملائكة يامريم إن الله اصطفاك وطهرك واصطفاك على نساء العالمين} [آل عمران: 42] مع الشهادات للسيد المسيح بالمعجزات وأنه حبلت به أمه من غير مباضعة رجل لبشارة ملائكة الله لأمه وأنه تكلم في المهد وأحيا الميت وأبرأ الأكمه ونقى الأبرص وأنه خلق من الطين كهيئة الطير فنفخ فيه فكان طائرا بإذن الله أي بإذن اللاهوت الذي هو كلمة …","ref":"ابن تيمية في «الجواب الصحيح»","id":"jawab-sahih:54","sec":"فصل: توسط المسلمين بين تقصير اليهود وغلو النصارى (1)"}]}]},{"id":"thanawiyya","t":"المجوس والثنوية: إلهان للنور والظلمة؟","intro":"قالت المجوس والثنوية بأصلين: النور للخير والظلمة للشر. وهذا يبطله أن الله خالق النور والظلمة معاً، وأن التعدد في الخالق يفسد نظام الكون.","points":[{"t":"عقيدتهم كما وصفها الشهرستاني","d":"","ev":[{"k":"b","t":"أثبتوا أصلين كما ذكرنا، إلا أن المجوس الأصلية زعموا أن الأصلين لا يجوز أن يكونا قديمين أزليين، بل النور أزلي، والظلمة محدثة. ثم لهم اختلاف في سبب حدوثها: أمن النور حدثت؟ والنور لا يحدث شرا جزئيا، فكيف يحدث أصل الشر؟ أم من شيء آخر؟ ولا شيء يشرك النور في الإحداث والقدم؟. وبهذا يظهر خبط المجوس. وهؤلاء يقولون: المبدأ الأول من الأشخاص: كيومرث، وربما يقولون زروان الكبير، والنبي الثاني: زردشت. و الكيومرثية يقولون: كيومرث هو آدم عليه السلام، وتفسير كيومرث هو: الحي الناطق. وقد ورد في تواريخ الهند والعجم أن كيومرث هو آدم …","ref":"الشهرستاني: المجوس","id":"milal:107","sec":"الفصل الأول: المجوس"},{"k":"b","t":"هؤلاء هم أصحاب الاثنين الأزليين. يزعمون أن النور والظلمة أزليان قديمان، بخلاف المجوس، فإنهم قالوا بحدوث الظلام، وذكروا سبب حدوثه. وهؤلاء قالوا بتساويهما في القدم، واختلافهما في الجوهر، والطبع، والفعل، والحيز، والمكان والأجناس، والأبدان والأرواح.","ref":"الشهرستاني: الثنوية","id":"milal:112","sec":"الفصل الثاني: الثنوية"}]},{"t":"الرد عليهم","d":"","ev":[{"k":"b","t":"قال أبو محمد رضي الله عنه افترق القائلون بأن فاعل العالم أكثر من واحد فرقا ثم ترجع هذه الفرق إلى فرقتين فإحدى الفرقتين تذهب إلى أن العالم غير مدبريه وهم القائلون بتدبير الكواكب السبعة وأزليتها وهم المجوس فإن المتكلمين ذكروا عنهم أنهم يقولون أن الباري عز وجل لما طالت وحدته استوحش فلما استوحش فكر فكرة سوء فتجسمت فاستحالت ظلمة فحدث منها اهرمن وهو إبليس فرام البارىء تعالى إبعاده عن نفسه يستطع فتحرز منه بخلق الخيرات وشرع اهرمن في خلق الشر ولهم في ذلك تخليط كثير قال أبو محمد رضي الله عنه وهذا أمر لا تعرفه المجوس قولهم …","ref":"ابن حزم: الكلام على من قال إن فاعل العالم أكثر من واحد","id":"fisal:6","sec":"الكلام على من قال أن فاعل العالم ومدبره أكثر من واحد (1)"}]},{"t":"وجعل الظلمات والنور","d":"","ev":[{"k":"q","t":"ٱلْحَمْدُ لِلَّهِ ٱلَّذِى خَلَقَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ وَجَعَلَ ٱلظُّلُمَـٰتِ وَٱلنُّورَ ۖ ثُمَّ ٱلَّذِينَ كَفَرُوا۟ بِرَبِّهِمْ يَعْدِلُونَ ﴿1﴾","ref":"الأنعام: 1","id":"quran:6:1"},{"k":"q","t":"لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا ۚ فَسُبْحَـٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ ﴿22﴾","ref":"الأنبياء: 22","id":"quran:21:22"}]}]},{"id":"asnam","t":"عبادة الأصنام والكواكب والبشر","intro":"كل ما يُعبد من دون الله مخلوق محتاج لا يملك لنفسه نفعاً ولا ضراً، وهذه حجة إبراهيم عليه السلام مع قومه حين رأى الكوكب والقمر والشمس تأفل.","points":[{"t":"حجة إبراهيم مع عبدة الكواكب","d":"","ev":[{"k":"q","t":"فَلَمَّا جَنَّ عَلَيْهِ ٱلَّيْلُ رَءَا كَوْكَبًا ۖ قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَآ أُحِبُّ ٱلْـَٔافِلِينَ ﴿76﴾ فَلَمَّا رَءَا ٱلْقَمَرَ بَازِغًا قَالَ هَـٰذَا رَبِّى ۖ فَلَمَّآ أَفَلَ قَالَ لَئِن لَّمْ يَهْدِنِى رَبِّى لَأَكُونَنَّ مِنَ ٱلْقَوْمِ ٱلضَّآلِّينَ ﴿77﴾ فَلَمَّا رَءَا ٱلشَّمْسَ بَازِغَةً قَالَ هَـٰذَا رَبِّى هَـٰذَآ أَكْبَرُ ۖ فَلَمَّآ أَفَلَتْ قَالَ يَـٰقَوْمِ إِنِّى بَرِىٓءٌ مِّمَّا تُشْرِكُونَ ﴿78﴾ إِنِّى وَجَّهْتُ وَجْهِىَ لِلَّذِى فَطَرَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ حَنِيفًا ۖ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ ﴿79﴾","ref":"الأنعام: 76–79","id":"quran:6:76"}]},{"t":"ضعف الطالب والمطلوب","d":"","ev":[{"k":"q","t":"يَـٰٓأَيُّهَا ٱلنَّاسُ ضُرِبَ مَثَلٌ فَٱسْتَمِعُوا۟ لَهُۥٓ ۚ إِنَّ ٱلَّذِينَ تَدْعُونَ مِن دُونِ ٱللَّهِ لَن يَخْلُقُوا۟ ذُبَابًا وَلَوِ ٱجْتَمَعُوا۟ لَهُۥ ۖ وَإِن يَسْلُبْهُمُ ٱلذُّبَابُ شَيْـًٔا لَّا يَسْتَنقِذُوهُ مِنْهُ ۚ ضَعُفَ ٱلطَّالِبُ وَٱلْمَطْلُوبُ ﴿73﴾","ref":"الحج: 73","id":"quran:22:73"}]},{"t":"كيف نشأت عبادة الأصنام","d":"","ev":[{"k":"b","t":"اعلم أن الأصناف التي ذكرنا مذاهبهم يرجعون آخر الأمر إلى عبادة الأصنام، إذا كان لا يستمر لهم طريقة إلا بشخص حاضر ينظرون إليه ويعكفون عليه، وعن هذا اتخذت أصحاب الروحانيات والكواكب أصناما زعموا أنها على صورتها. وبالجملة وضع الأصنام حيث ما قدروه إنما هو على معبود غائب حتى يكون الصنم المعمول على صورته وشكله وهيأته نائبا منابه وقائما مقامه، وإلا فنعلم قطعا أن عاقلا ما لا ينحت جسما بيده ويصوره صورة ثم يعتقد أنه إلهه وخالقه، وإله الكل وخالق الكل، إذ كان وجوده مسبوقا بوجود صانعه، وشكله يحدث بصنعة ناحته. لكن القوم لما عكفوا …","ref":"الشهرستاني: عبدة الأصنام","id":"milal:238","sec":"الفصل الرابع: عبدة الأصنام"}]}]},{"id":"hind","t":"البراهمة وإنكار النبوات","intro":"من الهند من أنكر النبوات أصلاً، والعقل يدل على حاجة البشر إلى الرسل، إذ لا يُعرف تفصيل ما يحبه الله وما يكرهه إلا بوحي.","points":[{"t":"قولهم كما نقله الشهرستاني","d":"","ev":[{"k":"b","t":"من الناس من يظن أنهم سموا براهمة لا نتسابهم إلى إبراهيم عليه السلام وذلك خطأ، فإن هؤلاء القوم هم المخصوصون بنفي النبوات أصلا ورأسا، فكيف يقولون بإبراهيم عليه السلام؟ والقوم الذين اعتقدوا نبوة إبراهيم عليه السلام من أهل الهند فهم الثنوية منهم القائلون بالنور والظلمة على رأي أصحاب الاثنين، وقد ذكرنا مذاهبهم، وهؤلاء البراهمة إنما انتسبوا إلى رجل منهم يقال له براهم، وقد مهد لهم نفي النبوات أصلا وقرر استحالة ذلك في العقول بوجوه: منها أن قال: إن الذي يأتي به الرسول لم يخل من أحد أمرين: إما أن يكون معقولا وإما أن لا يكون …","ref":"الشهرستاني: البراهمة","id":"milal:226","sec":"الفصل الأول: البراهمة"}]},{"t":"رسلاً مبشرين ومنذرين","d":"","ev":[{"k":"q","t":"رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا ﴿165﴾","ref":"النساء: 165","id":"quran:4:165"},{"k":"q","t":"وَلَقَدْ بَعَثْنَا فِى كُلِّ أُمَّةٍ رَّسُولًا أَنِ ٱعْبُدُوا۟ ٱللَّهَ وَٱجْتَنِبُوا۟ ٱلطَّـٰغُوتَ ۖ فَمِنْهُم مَّنْ هَدَى ٱللَّهُ وَمِنْهُم مَّنْ حَقَّتْ عَلَيْهِ ٱلضَّلَـٰلَةُ ۚ فَسِيرُوا۟ فِى ٱلْأَرْضِ فَٱنظُرُوا۟ كَيْفَ كَانَ عَـٰقِبَةُ ٱلْمُكَذِّبِينَ ﴿36﴾","ref":"النحل: 36","id":"quran:16:36"}]}]},{"id":"tanasukh","t":"تناسخ الأرواح","intro":"يقول بعض أهل الهند وغيرهم بانتقال الأرواح بعد الموت إلى أجساد أخرى. والقرآن يبين أن بعد الموت برزخاً ثم بعثاً وحساباً، ولا رجعة إلى الدنيا.","points":[{"t":"ومن ورائهم برزخ","d":"","ev":[{"k":"q","t":"حَتَّىٰٓ إِذَا جَآءَ أَحَدَهُمُ ٱلْمَوْتُ قَالَ رَبِّ ٱرْجِعُونِ ﴿99﴾ لَعَلِّىٓ أَعْمَلُ صَـٰلِحًا فِيمَا تَرَكْتُ ۚ كَلَّآ ۚ إِنَّهَا كَلِمَةٌ هُوَ قَآئِلُهَا ۖ وَمِن وَرَآئِهِم بَرْزَخٌ إِلَىٰ يَوْمِ يُبْعَثُونَ ﴿100﴾","ref":"المؤمنون: 99–100","id":"quran:23:99"}]},{"t":"رد ابن حزم","d":"","ev":[{"k":"b","t":"قال أبو محمد رضي الله عنه افترق القائلون بتناسخ الأرواح على فرقتين فذهبت الفرقة الواحدة إلى أن الأرواح تنتقل بعد مفارقتها الأجساد إلى أجساد أخر وإن لم تكن من نوع الأجساد التي فارقت وهذا قول أحمد بن حابط وأحمد بن نانوس تلميذه وأبي مسلم الخراساني ومحمد بن زكريا الرازي الطبيب صرح بذلك في كتابه الموسوم بالعلم الإلهي وهو قول القرامطة وقال الرازي في بعض كتبه لولا أنه لا سبيل إلى تخليص الأرواح عن الأجساد المتصورة بالصور الهيمية إلى الأجساد المتصورة بصور الإنسان إلا بالقتل والذبح لما جاز ذبح شيء من الحيوان ألبتة قال أبو …","ref":"ابن حزم: الكلام على من قال بتناسخ الأرواح","id":"fisal:15","sec":"الكلام على من قال بتناسخ الأرواح"}]}]}]},{"id":"mulhid","ic":"🧠","name":"دعوة اللادينيين والملحدين","intro":"أدلة وجود الله ووحدانيته بالعقل والفطرة والمشاهدة، والجواب عن الشبهات المشهورة، ومناقشة العلمانية بهدوء.","topics":[{"id":"fitra","t":"دليل الفطرة","intro":"الإقرار بالخالق مغروس في النفوس، ويظهر عند الشدائد حين تنقطع الأسباب، وما الإلحاد إلا غشاوة على هذه الفطرة.","points":[{"t":"فطرة الله","d":"","ev":[{"k":"q","t":"فَأَقِمْ وَجْهَكَ لِلدِّينِ حَنِيفًا ۚ فِطْرَتَ ٱللَّهِ ٱلَّتِى فَطَرَ ٱلنَّاسَ عَلَيْهَا ۚ لَا تَبْدِيلَ لِخَلْقِ ٱللَّهِ ۚ ذَٰلِكَ ٱلدِّينُ ٱلْقَيِّمُ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ ﴿30﴾","ref":"الروم: 30","id":"quran:30:30"},{"k":"h","t":"«كل مولود يولد على الفطرة...»","ref":"متفق عليه","id":"bukhari:1385"}]},{"t":"اللجوء إلى الله عند الشدة","d":"","ev":[{"k":"q","t":"هُوَ ٱلَّذِى يُسَيِّرُكُمْ فِى ٱلْبَرِّ وَٱلْبَحْرِ ۖ حَتَّىٰٓ إِذَا كُنتُمْ فِى ٱلْفُلْكِ وَجَرَيْنَ بِهِم بِرِيحٍ طَيِّبَةٍ وَفَرِحُوا۟ بِهَا جَآءَتْهَا رِيحٌ عَاصِفٌ وَجَآءَهُمُ ٱلْمَوْجُ مِن كُلِّ مَكَانٍ وَظَنُّوٓا۟ أَنَّهُمْ أُحِيطَ بِهِمْ ۙ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ لَئِنْ أَنجَيْتَنَا مِنْ هَـٰذِهِۦ لَنَكُونَنَّ مِنَ ٱلشَّـٰكِرِينَ ﴿22﴾","ref":"يونس: 22","id":"quran:10:22"},{"k":"q","t":"فَإِذَا رَكِبُوا۟ فِى ٱلْفُلْكِ دَعَوُا۟ ٱللَّهَ مُخْلِصِينَ لَهُ ٱلدِّينَ فَلَمَّا نَجَّىٰهُمْ إِلَى ٱلْبَرِّ إِذَا هُمْ يُشْرِكُونَ ﴿65﴾","ref":"العنكبوت: 65","id":"quran:29:65"}]},{"t":"كلام أهل العلم","d":"","ev":[{"k":"b","t":"… يفيد العم، ثم العلم يفيد العمل. ولهذا كان أكثر الناس على أن الإقرار بالصانع ضروري فطري، وذلك أن اضطرار النفوس إلى ذلك أعظم من اضطرارها إلى مالا تتعلق به حاجتها. ألا ترى أن الناس يعرفون من أحوال من تتعلق به منافعهم ومضارهم، كولاة أمورهم وممالكيهم، وأصدقائهم وأعدائهم، مالا يعلمونه من أحوال من لا يرجونه ولا يخافونه، ولا شيء أحوج إلى شيء من المخلوق إلى خالقه فهم يحتاجون إليه من جهة ربوبيته، إذ كان هو الذي خلقهم، …","ref":"ابن تيمية في «درء تعارض العقل والنقل»","id":"dar-taarud:255","sec":"تعليق ابن تيمية"}]}]},{"id":"huduth","t":"دليل الخلق والإيجاد","intro":"كل حادث لا بد له من مُحدِث؛ فالكون لم يخلق نفسه، ولم يخلق من عدم بلا خالق، فلا بد له من خالق.","points":[{"t":"السبر والتقسيم في آية","d":"هذه الآية تحصر الاحتمالات: إما من غير خالق، أو هم خلقوا أنفسهم، وكلاهما باطل، فلم يبق إلا أن الله خلقهم.","ev":[{"k":"q","t":"أَمْ خُلِقُوا۟ مِنْ غَيْرِ شَىْءٍ أَمْ هُمُ ٱلْخَـٰلِقُونَ ﴿35﴾ أَمْ خَلَقُوا۟ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضَ ۚ بَل لَّا يُوقِنُونَ ﴿36﴾","ref":"الطور: 35–36","id":"quran:52:35"}]},{"t":"كل حادث فله سبب","d":"","ev":[{"k":"b","t":"… المدرك بالمشاهدة الظاهرة والباطنة ، مثاله أنا إذا قلنا مثلا كل حادث فله سبب ، وفي العالم حوادث فلا بد لها من سبب . فقولنا : في العالم حوادث ، أصل واحد يجب الإقرار به ، فإنه يدرك بالمشاهدة الظاهرة حدوث أشخاص الحيوانات والنباتات والغيوم والامطار ومن الأعراض الأصوات والألوان . وان تخيل أنها منتقلة ، فالانتقال حادث ونحن لم ندع إلا حادثا ولم نعين أن ذلك الحادث جوهر أو عرض أو انتقال أو غيره . وكذلك …","ref":"الغزالي في «الاقتصاد في الاعتقاد»","id":"iqtisad:2","sec":"مقدمة (2)"},{"k":"b","t":"… حتى نأتي بالبراهين الظاهرة والنتائج الموجبة والقضايا الضرورية على إثبات حدوث العالم ولا قوة إلا بالله العلي العظيم فما اعترضوا به أن قالوا لم نر شيئا حدث إلا من شيء أو في شيء فمن ادعى غير ذلك فقد ادعى ما لا يشاهد ولم يشاهد وقالوا أيضا لا يخلو محدث الأجسام الجواهر والأعراض وهي كل ما في العالم إن كان العالم محدثا من أن يكون أحدثه لأنه أو إحداثه لعلة فإن كان لأنه فالعالم لم يزل لأن محدثه لم يزل وإذ هو علة …","ref":"ابن حزم في «الفِصَل»","id":"fisal:2","sec":"بسم الله الرحمن الرحيم (2)"}]}]},{"id":"itqan","t":"دليل الإتقان والعناية","intro":"النظام الدقيق في الكون والإنسان والكائنات يدل على خالق عليم حكيم؛ فالإتقان لا يأتي من المصادفة.","points":[{"t":"صنع الله الذي أتقن كل شيء","d":"","ev":[{"k":"q","t":"وَتَرَى ٱلْجِبَالَ تَحْسَبُهَا جَامِدَةً وَهِىَ تَمُرُّ مَرَّ ٱلسَّحَابِ ۚ صُنْعَ ٱللَّهِ ٱلَّذِىٓ أَتْقَنَ كُلَّ شَىْءٍ ۚ إِنَّهُۥ خَبِيرٌۢ بِمَا تَفْعَلُونَ ﴿88﴾","ref":"النمل: 88","id":"quran:27:88"},{"k":"q","t":"ٱلَّذِى خَلَقَ سَبْعَ سَمَـٰوَٰتٍ طِبَاقًا ۖ مَّا تَرَىٰ فِى خَلْقِ ٱلرَّحْمَـٰنِ مِن تَفَـٰوُتٍ ۖ فَٱرْجِعِ ٱلْبَصَرَ هَلْ تَرَىٰ مِن فُطُورٍ ﴿3﴾ ثُمَّ ٱرْجِعِ ٱلْبَصَرَ كَرَّتَيْنِ يَنقَلِبْ إِلَيْكَ ٱلْبَصَرُ خَاسِئًا وَهُوَ حَسِيرٌ ﴿4﴾","ref":"الملك: 3–4","id":"quran:67:3"}]},{"t":"في أنفسكم أفلا تبصرون","d":"","ev":[{"k":"q","t":"وَفِى ٱلْأَرْضِ ءَايَـٰتٌ لِّلْمُوقِنِينَ ﴿20﴾ وَفِىٓ أَنفُسِكُمْ ۚ أَفَلَا تُبْصِرُونَ ﴿21﴾","ref":"الذاريات: 20–21","id":"quran:51:20"},{"k":"q","t":"سَنُرِيهِمْ ءَايَـٰتِنَا فِى ٱلْـَٔافَاقِ وَفِىٓ أَنفُسِهِمْ حَتَّىٰ يَتَبَيَّنَ لَهُمْ أَنَّهُ ٱلْحَقُّ ۗ أَوَلَمْ يَكْفِ بِرَبِّكَ أَنَّهُۥ عَلَىٰ كُلِّ شَىْءٍ شَهِيدٌ ﴿53﴾","ref":"فصلت: 53","id":"quran:41:53"}]},{"t":"التفكر في السماء","d":"","ev":[{"k":"q","t":"أَفَلَمْ يَنظُرُوٓا۟ إِلَى ٱلسَّمَآءِ فَوْقَهُمْ كَيْفَ بَنَيْنَـٰهَا وَزَيَّنَّـٰهَا وَمَا لَهَا مِن فُرُوجٍ ﴿6﴾","ref":"ق: 6","id":"quran:50:6"},{"k":"b","t":"… إلى السماء فوقهم كيف بنيناها وزيناها ومالها من فروج فنحن ننظر كيف خلق السماء وكيف بناها وكيف صانها عن الفروج: النوع السابع أن إبراهيم عليه السلام لما استدل على إثبات الصانع تعالى بقوله ربى الذي يحي ويميت قال له نمرود أتدعى أنه يحي ويميت بواسطة الطبائع والعناصر أو لا بواسطة هذه الأشياء فان ادعيت الأول فلذلك مما لا تجده البتة لأن كل ما يحدث في هذا العالم فإنما يحدث بواسطة أحوال العناصر الأربعة والحركات الفلكية …","ref":"ابن القيم في «مفتاح دار السعادة»","id":"miftah-sada:210","sec":"فصل قال صاحب الرسالة ذكر جمل من احتجاجهم والاحتجاج عليهم من إوكد (1)"}]},{"t":"العقل والشرع متفقان","d":"","ev":[{"k":"b","t":"… القطع أنه لا يؤدي النظر البرهأني إلى مخالفة ما ورد به الشرع. فإن الحق لا يضاد الحق، بل يوافقه ويشهد له. وإذا كأن هذا هكذا، فإن أدى النظر البرهاني إلى نحو ما من المعرفة بموجود ما، فلا يخلو ذلك الموجود أن يكون قد سكت عنه في الشرع أو عرف به. فإن كأن مما قد سكت عنه فلا تعارض هنالك، هو بمنزلة ما سكت عنه من الأحكام، فاستنبطها الفقيه بالقياس الشرعي. وأن كانت الشريعة نطقت به، فلا يخلو ظاهر النطق أن يكون موافقا …","ref":"ابن رشد في «فصل المقال»","id":"fasl-maqal:6","sec":"موافقة الشريعة لمناهج الفلسفة"}]}]},{"id":"hidaya","t":"دليل الهداية والتسخير","intro":"كل مخلوق هُدي لما يصلحه: النحلة لبيتها، والطفل لثدي أمه، والطير لهجرته؛ فمن علّمها؟","points":[{"t":"أعطى كل شيء خلقه ثم هدى","d":"","ev":[{"k":"q","t":"قَالَ فَمَن رَّبُّكُمَا يَـٰمُوسَىٰ ﴿49﴾ قَالَ رَبُّنَا ٱلَّذِىٓ أَعْطَىٰ كُلَّ شَىْءٍ خَلْقَهُۥ ثُمَّ هَدَىٰ ﴿50﴾","ref":"طه: 49–50","id":"quran:20:49"},{"k":"q","t":"سَبِّحِ ٱسْمَ رَبِّكَ ٱلْأَعْلَى ﴿1﴾ ٱلَّذِى خَلَقَ فَسَوَّىٰ ﴿2﴾ وَٱلَّذِى قَدَّرَ فَهَدَىٰ ﴿3﴾","ref":"الأعلى: 1–3","id":"quran:87:1"}]},{"t":"النحل آية","d":"","ev":[{"k":"q","t":"وَأَوْحَىٰ رَبُّكَ إِلَى ٱلنَّحْلِ أَنِ ٱتَّخِذِى مِنَ ٱلْجِبَالِ بُيُوتًا وَمِنَ ٱلشَّجَرِ وَمِمَّا يَعْرِشُونَ ﴿68﴾ ثُمَّ كُلِى مِن كُلِّ ٱلثَّمَرَٰتِ فَٱسْلُكِى سُبُلَ رَبِّكِ ذُلُلًا ۚ يَخْرُجُ مِنۢ بُطُونِهَا شَرَابٌ مُّخْتَلِفٌ أَلْوَٰنُهُۥ فِيهِ شِفَآءٌ لِّلنَّاسِ ۗ إِنَّ فِى ذَٰلِكَ لَـَٔايَةً لِّقَوْمٍ يَتَفَكَّرُونَ ﴿69﴾","ref":"النحل: 68–69","id":"quran:16:68"}]}]},{"id":"wahdaniyya","t":"أدلة الوحدانية","intro":"لو كان مع الله إله آخر لاختلف التدبير وفسد الكون، وانتظامه دليل على أن مدبّره واحد.","points":[{"t":"دليل التمانع","d":"","ev":[{"k":"q","t":"لَوْ كَانَ فِيهِمَآ ءَالِهَةٌ إِلَّا ٱللَّهُ لَفَسَدَتَا ۚ فَسُبْحَـٰنَ ٱللَّهِ رَبِّ ٱلْعَرْشِ عَمَّا يَصِفُونَ ﴿22﴾","ref":"الأنبياء: 22","id":"quran:21:22"},{"k":"q","t":"مَا ٱتَّخَذَ ٱللَّهُ مِن وَلَدٍ وَمَا كَانَ مَعَهُۥ مِنْ إِلَـٰهٍ ۚ إِذًا لَّذَهَبَ كُلُّ إِلَـٰهٍۭ بِمَا خَلَقَ وَلَعَلَا بَعْضُهُمْ عَلَىٰ بَعْضٍ ۚ سُبْحَـٰنَ ٱللَّهِ عَمَّا يَصِفُونَ ﴿91﴾","ref":"المؤمنون: 91","id":"quran:23:91"},{"k":"b","t":"… الأمر تولد منه اضطراب وفساد وهو الذي أراد الله سبحانه بقوله ' لو كان فيهما آلهة إلا الله لفسدتا ' فلا مزيد على بيان القرآن . ولنختم هذا القطب بالدعوى العاشرة فلم يبق مما يليق بهذا الفن إلا بيان استحالة كونه سبحانه محلا للحوادث ، وسنشير إليه في أثناء الكلام في الصفات ردا على من قال بحدوث العلم والإرادة وغيرهما . | القطب الثاني في الصفات الإلهية وفيه سبعة دعاوى إذ ندعى أنه سبحانه قادر عالم حي مريد …","ref":"الغزالي","id":"iqtisad:7","sec":"مقدمة (7)"}]},{"t":"قل هو الله أحد","d":"","ev":[{"k":"q","t":"قُلْ هُوَ ٱللَّهُ أَحَدٌ ﴿1﴾ ٱللَّهُ ٱلصَّمَدُ ﴿2﴾ لَمْ يَلِدْ وَلَمْ يُولَدْ ﴿3﴾ وَلَمْ يَكُن لَّهُۥ كُفُوًا أَحَدٌۢ ﴿4﴾","ref":"الإخلاص: 1–4","id":"quran:112:1"}]}]},{"id":"man-khalaq","t":"شبهة: من خلق الله؟","intro":"الخالق لا يكون مخلوقاً، وإلا لاحتاج إلى خالق، ولتسلسل الأمر إلى ما لا نهاية، فلا يوجد شيء أصلاً. فوجود الكون يدل على خالق أول لا أول له. وقد أرشد النبي ﷺ إلى قطع هذا الوسواس.","points":[{"t":"الهدي النبوي","d":"","ev":[{"k":"h","t":"«يأتي الشيطان أحدكم فيقول: من خلق كذا؟ من خلق كذا؟ حتى يقول: من خلق ربك؟ فإذا بلغه فليستعذ بالله ولينته»","ref":"متفق عليه","id":"bukhari:3276"}]},{"t":"هو الأول والآخر","d":"","ev":[{"k":"q","t":"هُوَ ٱلْأَوَّلُ وَٱلْـَٔاخِرُ وَٱلظَّـٰهِرُ وَٱلْبَاطِنُ ۖ وَهُوَ بِكُلِّ شَىْءٍ عَلِيمٌ ﴿3﴾","ref":"الحديد: 3","id":"quran:57:3"}]}]},{"id":"sharr","t":"شبهة: لماذا الشر والألم؟","intro":"الدنيا دار ابتلاء لا دار جزاء، والشر فيها نسبي جزئي تحته حِكم: الصبر، والرحمة، والتوبة، وتمييز الصادق. والله لا يخلق شراً محضاً.","points":[{"t":"الحياة امتحان","d":"","ev":[{"k":"q","t":"ٱلَّذِى خَلَقَ ٱلْمَوْتَ وَٱلْحَيَوٰةَ لِيَبْلُوَكُمْ أَيُّكُمْ أَحْسَنُ عَمَلًا ۚ وَهُوَ ٱلْعَزِيزُ ٱلْغَفُورُ ﴿2﴾","ref":"الملك: 2","id":"quran:67:2"},{"k":"q","t":"كُلُّ نَفْسٍ ذَآئِقَةُ ٱلْمَوْتِ ۗ وَنَبْلُوكُم بِٱلشَّرِّ وَٱلْخَيْرِ فِتْنَةً ۖ وَإِلَيْنَا تُرْجَعُونَ ﴿35﴾","ref":"الأنبياء: 35","id":"quran:21:35"}]},{"t":"والعاقبة للصابرين","d":"المصائب تكشف معادن الناس وترفع درجات الصابرين.","ev":[{"k":"q","t":"وَلَنَبْلُوَنَّكُم بِشَىْءٍ مِّنَ ٱلْخَوْفِ وَٱلْجُوعِ وَنَقْصٍ مِّنَ ٱلْأَمْوَٰلِ وَٱلْأَنفُسِ وَٱلثَّمَرَٰتِ ۗ وَبَشِّرِ ٱلصَّـٰبِرِينَ ﴿155﴾ ٱلَّذِينَ إِذَآ أَصَـٰبَتْهُم مُّصِيبَةٌ قَالُوٓا۟ إِنَّا لِلَّهِ وَإِنَّآ إِلَيْهِ رَٰجِعُونَ ﴿156﴾ أُو۟لَـٰٓئِكَ عَلَيْهِمْ صَلَوَٰتٌ مِّن رَّبِّهِمْ وَرَحْمَةٌ ۖ وَأُو۟لَـٰٓئِكَ هُمُ ٱلْمُهْتَدُونَ ﴿157﴾","ref":"البقرة: 155–157","id":"quran:2:155"}]},{"t":"والشر ليس إليك","d":"","ev":[{"k":"b","t":"… كما قال تعالى بيده الخير وقال أعرف الخلق به: \"والشر ليس إليك\" فهو لا يخلق شرا محضا من كل وجه بل كل ما خلقه ففي خلقه مصلحة وحكمة وإن كان في بعضه شر جزئي إضافي وأما الشر الكلي المطلق من كل وجه فهو تعالى منزه عنه وليس إليه، الفرق السادس أن ما يحصل للإنسان من الحسنات التي يعملها فهي أمور وجودية متعلقة بمشيئة الرب وقدره ورحمته وحكمته وليست أمورا عدمية تضاف إلى غير الله بل هي كلها أمور وجودية وكل موجود حادث …","ref":"ابن القيم في «شفاء العليل»","id":"shifa-alil:49","sec":"الباب العشرون: في ذكر مناظرة بين قدري وسني (5)"}]}]},{"id":"abath","t":"شبهة: الحياة بلا غاية","intro":"العقل يأبى أن يكون هذا الكون المتقن عبثاً بلا غاية؛ فالغاية عبادة الله، والجزاء العادل في الآخرة.","points":[{"t":"أفحسبتم أنما خلقناكم عبثاً","d":"","ev":[{"k":"q","t":"أَفَحَسِبْتُمْ أَنَّمَا خَلَقْنَـٰكُمْ عَبَثًا وَأَنَّكُمْ إِلَيْنَا لَا تُرْجَعُونَ ﴿115﴾","ref":"المؤمنون: 115","id":"quran:23:115"},{"k":"q","t":"أَيَحْسَبُ ٱلْإِنسَـٰنُ أَن يُتْرَكَ سُدًى ﴿36﴾","ref":"القيامة: 36","id":"quran:75:36"}]},{"t":"الغاية من الخلق","d":"","ev":[{"k":"q","t":"وَمَا خَلَقْتُ ٱلْجِنَّ وَٱلْإِنسَ إِلَّا لِيَعْبُدُونِ ﴿56﴾","ref":"الذاريات: 56","id":"quran:51:56"}]}]},{"id":"aql","t":"العقل والدين لا يتعارضان","intro":"القرآن يدعو إلى النظر والتفكر، والعقل الصريح لا يعارض النقل الصحيح أبداً.","points":[{"t":"دعوة القرآن إلى التفكر","d":"","ev":[{"k":"q","t":"إِنَّ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ وَٱخْتِلَـٰفِ ٱلَّيْلِ وَٱلنَّهَارِ لَـَٔايَـٰتٍ لِّأُو۟لِى ٱلْأَلْبَـٰبِ ﴿190﴾ ٱلَّذِينَ يَذْكُرُونَ ٱللَّهَ قِيَـٰمًا وَقُعُودًا وَعَلَىٰ جُنُوبِهِمْ وَيَتَفَكَّرُونَ فِى خَلْقِ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ رَبَّنَا مَا خَلَقْتَ هَـٰذَا بَـٰطِلًا سُبْحَـٰنَكَ فَقِنَا عَذَابَ ٱلنَّارِ ﴿191﴾","ref":"آل عمران: 190–191","id":"quran:3:190"}]},{"t":"درء التعارض","d":"","ev":[{"k":"b","t":"… كثيرون ك أبي حامد والشهرستاني وأبي القاسم الراغب وغيرهم يقولون: العلم بالصانع فطري ضروري. والرازي والآمدي وغيرهما من النظار يسلمون أن العلم بالصانع قد يحصل بالاضطرار، وحينئذ فالعلم بكون الصانع قادرا معلوم بالاضطرار، والعلم بصدق الرسول عند ظهور المعجزات التي تحدي الخلق بمعارضتها وعجزوا عن ذلك معلوم بالاضطرار. ومعلوم أن السمعيات مملوءة من إثبات الصانع وقدرته وتصديق رسوله، ليس فيها ما يناقض هذه الأصول العقلية …","ref":"ابن تيمية","id":"dar-taarud:33","sec":"الثاني"},{"k":"b","t":"… القطع أنه لا يؤدي النظر البرهأني إلى مخالفة ما ورد به الشرع. فإن الحق لا يضاد الحق، بل يوافقه ويشهد له. وإذا كأن هذا هكذا، فإن أدى النظر البرهاني إلى نحو ما من المعرفة بموجود ما، فلا يخلو ذلك الموجود أن يكون قد سكت عنه في الشرع أو عرف به. فإن كأن مما قد سكت عنه فلا تعارض هنالك، هو بمنزلة ما سكت عنه من الأحكام، فاستنبطها الفقيه بالقياس الشرعي. وأن كانت الشريعة نطقت به، فلا يخلو ظاهر النطق أن يكون موافقا …","ref":"ابن رشد","id":"fasl-maqal:6","sec":"موافقة الشريعة لمناهج الفلسفة"}]}]},{"id":"ilmaniyya","t":"العلمانية وفصل الدين عن الحياة","intro":"الإسلام دين يشمل العبادة والمعاملة والأخلاق والحكم؛ فالمسلم يعبد الله في صلاته وفي سوقه وفي بيته.","points":[{"t":"الحياة كلها لله","d":"","ev":[{"k":"q","t":"قُلْ إِنَّ صَلَاتِى وَنُسُكِى وَمَحْيَاىَ وَمَمَاتِى لِلَّهِ رَبِّ ٱلْعَـٰلَمِينَ ﴿162﴾ لَا شَرِيكَ لَهُۥ ۖ وَبِذَٰلِكَ أُمِرْتُ وَأَنَا۠ أَوَّلُ ٱلْمُسْلِمِينَ ﴿163﴾","ref":"الأنعام: 162–163","id":"quran:6:162"}]},{"t":"التحاكم إلى شرع الله","d":"","ev":[{"k":"q","t":"فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا۟ فِىٓ أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا۟ تَسْلِيمًا ﴿65﴾","ref":"النساء: 65","id":"quran:4:65"},{"k":"q","t":"أَفَحُكْمَ ٱلْجَـٰهِلِيَّةِ يَبْغُونَ ۚ وَمَنْ أَحْسَنُ مِنَ ٱللَّهِ حُكْمًا لِّقَوْمٍ يُوقِنُونَ ﴿50﴾","ref":"المائدة: 50","id":"quran:5:50"}]}]},{"id":"baath","t":"البعث والجزاء","intro":"الذي خلق أول مرة قادر على الإعادة، والعدل يقتضي يوماً يُجزى فيه المحسن والمسيء.","points":[{"t":"من يحيي العظام وهي رميم","d":"","ev":[{"k":"q","t":"وَضَرَبَ لَنَا مَثَلًا وَنَسِىَ خَلْقَهُۥ ۖ قَالَ مَن يُحْىِ ٱلْعِظَـٰمَ وَهِىَ رَمِيمٌ ﴿78﴾ قُلْ يُحْيِيهَا ٱلَّذِىٓ أَنشَأَهَآ أَوَّلَ مَرَّةٍ ۖ وَهُوَ بِكُلِّ خَلْقٍ عَلِيمٌ ﴿79﴾","ref":"يس: 78–79","id":"quran:36:78"}]},{"t":"الاستدلال بالخلق الأول","d":"","ev":[{"k":"q","t":"يَـٰٓأَيُّهَا ٱلنَّاسُ إِن كُنتُمْ فِى رَيْبٍ مِّنَ ٱلْبَعْثِ فَإِنَّا خَلَقْنَـٰكُم مِّن تُرَابٍ ثُمَّ مِن نُّطْفَةٍ ثُمَّ مِنْ عَلَقَةٍ ثُمَّ مِن مُّضْغَةٍ مُّخَلَّقَةٍ وَغَيْرِ مُخَلَّقَةٍ لِّنُبَيِّنَ لَكُمْ ۚ وَنُقِرُّ فِى ٱلْأَرْحَامِ مَا نَشَآءُ إِلَىٰٓ أَجَلٍ مُّسَمًّى ثُمَّ نُخْرِجُكُمْ طِفْلًا ثُمَّ لِتَبْلُغُوٓا۟ أَشُدَّكُمْ ۖ وَمِنكُم مَّن يُتَوَفَّىٰ وَمِنكُم مَّن يُرَدُّ إِلَىٰٓ أَرْذَلِ ٱلْعُمُرِ لِكَيْلَا يَعْلَمَ مِنۢ بَعْدِ عِلْمٍ شَيْـًٔا ۚ وَتَرَى ٱلْأَرْضَ هَامِدَةً فَإِذَآ أَنزَلْنَا عَلَيْهَا ٱلْمَآءَ ٱهْتَزَّتْ وَرَبَتْ وَأَنۢبَتَتْ مِن كُلِّ زَوْجٍۭ بَهِيجٍ ﴿5﴾","ref":"الحج: 5","id":"quran:22:5"}]},{"t":"العدل يقتضي الجزاء","d":"","ev":[{"k":"q","t":"أَمْ نَجْعَلُ ٱلَّذِينَ ءَامَنُوا۟ وَعَمِلُوا۟ ٱلصَّـٰلِحَـٰتِ كَٱلْمُفْسِدِينَ فِى ٱلْأَرْضِ أَمْ نَجْعَلُ ٱلْمُتَّقِينَ كَٱلْفُجَّارِ ﴿28﴾","ref":"ص: 28","id":"quran:38:28"}]}]},{"id":"dahr","t":"الدهرية: لا يهلكنا إلا الدهر","intro":"قول الدهريين قديم: لا حياة إلا الدنيا والزمن هو الذي يُفني. والقرآن يبين أنه ظن بلا علم.","points":[{"t":"قولهم في القرآن","d":"","ev":[{"k":"q","t":"وَقَالُوا۟ مَا هِىَ إِلَّا حَيَاتُنَا ٱلدُّنْيَا نَمُوتُ وَنَحْيَا وَمَا يُهْلِكُنَآ إِلَّا ٱلدَّهْرُ ۚ وَمَا لَهُم بِذَٰلِكَ مِنْ عِلْمٍ ۖ إِنْ هُمْ إِلَّا يَظُنُّونَ ﴿24﴾","ref":"الجاثية: 24","id":"quran:45:24"}]},{"t":"ما لهم بذلك من علم","d":"","ev":[{"k":"q","t":"وَإِذَا تُتْلَىٰ عَلَيْهِمْ ءَايَـٰتُنَا بَيِّنَـٰتٍ مَّا كَانَ حُجَّتَهُمْ إِلَّآ أَن قَالُوا۟ ٱئْتُوا۟ بِـَٔابَآئِنَآ إِن كُنتُمْ صَـٰدِقِينَ ﴿25﴾ قُلِ ٱللَّهُ يُحْيِيكُمْ ثُمَّ يُمِيتُكُمْ ثُمَّ يَجْمَعُكُمْ إِلَىٰ يَوْمِ ٱلْقِيَـٰمَةِ لَا رَيْبَ فِيهِ وَلَـٰكِنَّ أَكْثَرَ ٱلنَّاسِ لَا يَعْلَمُونَ ﴿26﴾","ref":"الجاثية: 25–26","id":"quran:45:25"}]}]},{"id":"akhlaq2","t":"الأخلاق بلا إله؟","intro":"إذا لم يكن خالق ولا حساب، فلا يبقى للخير والشر معيار ثابت؛ أما المؤمن فيعلم أن الله ألهم النفس الفجور والتقوى، وأن الأخلاق عبادة.","points":[{"t":"ونفس وما سواها","d":"","ev":[{"k":"q","t":"وَنَفْسٍ وَمَا سَوَّىٰهَا ﴿7﴾ فَأَلْهَمَهَا فُجُورَهَا وَتَقْوَىٰهَا ﴿8﴾ قَدْ أَفْلَحَ مَن زَكَّىٰهَا ﴿9﴾ وَقَدْ خَابَ مَن دَسَّىٰهَا ﴿10﴾","ref":"الشمس: 7–10","id":"quran:91:7"}]},{"t":"إنما بعثت لأتمم","d":"","ev":[{"k":"h","t":"«إنما بُعثت لأتمم صالح الأخلاق»","ref":"رواه أحمد","id":"ahmad:8595"}]}]},{"id":"nubuwwa2","t":"حاجة البشر إلى الرسل","intro":"العقل يعرف وجود الله، لكنه لا يستقل بمعرفة تفاصيل ما يحبه وما يرضاه؛ فكانت الرسالة رحمة.","points":[{"t":"لئلا يكون للناس حجة","d":"","ev":[{"k":"q","t":"رُّسُلًا مُّبَشِّرِينَ وَمُنذِرِينَ لِئَلَّا يَكُونَ لِلنَّاسِ عَلَى ٱللَّهِ حُجَّةٌۢ بَعْدَ ٱلرُّسُلِ ۚ وَكَانَ ٱللَّهُ عَزِيزًا حَكِيمًا ﴿165﴾","ref":"النساء: 165","id":"quran:4:165"}]},{"t":"مناظرة الصابئة والحنفاء","d":"","ev":[{"k":"b","t":"وقد جري مناظرات ومحاورات بين الصابئة والحنفاء في المفاضلة بين الروحاني المحض وبين البشرية النبوية. ونحن أردنا أن نوردها على شكل سؤال وجواب، وفيها فوائد لا تحصى: قالت الصابئة: الروحانيات أبدعت إبداعا، لا من شيء لا مادة، ولا هيولى، وهي كلها جوهر واحد، على سنخ1 واحد وجواهرها أنوار محضة لا ظلام فيها، وهي من شدة ضيائها لا يدركها الحس، ولا ينالها البصر، ومن غاية لطافتها يحار فيها العقل، ولا يجول فيها الخيال. ونوع الإنسان مركب من العناصر الأربعة، مؤلف من مادة وصورة، والعناصر متضادة ومزدوجة بطباعها. اثنان منها مزدوجان، …","ref":"الشهرستاني: مناظرات بين الصابئة والحنفاء","id":"milal:123","sec":"2- مناظرات بين الصابئة، والحنفاء (1)"}]}]}]},{"id":"turuq","ic":"📣","name":"فقه الدعوة: كن داعياً لدين ربك","intro":"طرق الدعوة بالحكمة والموعظة الحسنة: لكل مسلم ومسلمة، للشباب والفتيات والكبار، بالقول والقدوة.","topics":[{"id":"fadl","t":"فضل الدعوة إلى الله","intro":"الدعوة وظيفة الأنبياء، وأجرها عظيم.","points":[{"t":"أحسن القول","d":"","ev":[{"k":"q","t":"وَمَنْ أَحْسَنُ قَوْلًا مِّمَّن دَعَآ إِلَى ٱللَّهِ وَعَمِلَ صَـٰلِحًا وَقَالَ إِنَّنِى مِنَ ٱلْمُسْلِمِينَ ﴿33﴾","ref":"فصلت: 33","id":"quran:41:33"}]},{"t":"خير من حمر النعم","d":"","ev":[{"k":"h","t":"«فوالله لأن يهدي الله بك رجلاً واحداً خير لك من أن يكون لك حُمْر النعم»","ref":"متفق عليه","id":"bukhari:2942"}]},{"t":"من دل على هدى","d":"","ev":[{"k":"h","t":"«من دعا إلى هدى كان له من الأجر مثل أجور من تبعه، لا ينقص ذلك من أجورهم شيئاً»","ref":"رواه مسلم","id":"muslim:6804"}]},{"t":"بلّغوا ولو آية","d":"","ev":[{"k":"h","t":"«بلّغوا عني ولو آية»","ref":"رواه البخاري","id":"bukhari:3461"}]}]},{"id":"hikma","t":"الحكمة والموعظة الحسنة","intro":"الحكمة: وضع الشيء في موضعه، واختيار الأسلوب المناسب للشخص والوقت.","points":[{"t":"منهج الدعوة في آية","d":"","ev":[{"k":"q","t":"ٱدْعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلْحِكْمَةِ وَٱلْمَوْعِظَةِ ٱلْحَسَنَةِ ۖ وَجَـٰدِلْهُم بِٱلَّتِى هِىَ أَحْسَنُ ۚ إِنَّ رَبَّكَ هُوَ أَعْلَمُ بِمَن ضَلَّ عَن سَبِيلِهِۦ ۖ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ ﴿125﴾","ref":"النحل: 125","id":"quran:16:125"}]},{"t":"القول اللين حتى مع فرعون","d":"","ev":[{"k":"q","t":"ٱذْهَبَآ إِلَىٰ فِرْعَوْنَ إِنَّهُۥ طَغَىٰ ﴿43﴾ فَقُولَا لَهُۥ قَوْلًا لَّيِّنًا لَّعَلَّهُۥ يَتَذَكَّرُ أَوْ يَخْشَىٰ ﴿44﴾","ref":"طه: 43–44","id":"quran:20:43"}]},{"t":"على بصيرة","d":"","ev":[{"k":"q","t":"قُلْ هَـٰذِهِۦ سَبِيلِىٓ أَدْعُوٓا۟ إِلَى ٱللَّهِ ۚ عَلَىٰ بَصِيرَةٍ أَنَا۠ وَمَنِ ٱتَّبَعَنِى ۖ وَسُبْحَـٰنَ ٱللَّهِ وَمَآ أَنَا۠ مِنَ ٱلْمُشْرِكِينَ ﴿108﴾","ref":"يوسف: 108","id":"quran:12:108"}]}]},{"id":"rifq","t":"الرفق والتيسير","intro":"الغلظة تنفّر، والرفق يفتح القلوب.","points":[{"t":"يسّروا ولا تعسّروا","d":"","ev":[{"k":"h","t":"«يسّروا ولا تعسّروا، وبشّروا ولا تنفّروا»","ref":"متفق عليه","id":"bukhari:69"}]},{"t":"الأعرابي في المسجد","d":"بال أعرابي في المسجد فقام الناس إليه، فعلّمهم النبي ﷺ الرفق.","ev":[{"k":"h","t":"«دعوه، وهريقوا على بوله سَجلاً من ماء... فإنما بُعثتم ميسّرين ولم تُبعثوا معسّرين»","ref":"رواه البخاري","id":"bukhari:220"}]},{"t":"لو كنت فظاً","d":"","ev":[{"k":"q","t":"فَبِمَا رَحْمَةٍ مِّنَ ٱللَّهِ لِنتَ لَهُمْ ۖ وَلَوْ كُنتَ فَظًّا غَلِيظَ ٱلْقَلْبِ لَٱنفَضُّوا۟ مِنْ حَوْلِكَ ۖ فَٱعْفُ عَنْهُمْ وَٱسْتَغْفِرْ لَهُمْ وَشَاوِرْهُمْ فِى ٱلْأَمْرِ ۖ فَإِذَا عَزَمْتَ فَتَوَكَّلْ عَلَى ٱللَّهِ ۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلْمُتَوَكِّلِينَ ﴿159﴾","ref":"آل عمران: 159","id":"quran:3:159"}]}]},{"id":"tadarruj","t":"التدرج والبدء بالأهم","intro":"ابدأ بالتوحيد وأصول الإيمان قبل التفاصيل، وراعِ قدرة المدعو.","points":[{"t":"وصية معاذ إلى اليمن","d":"","ev":[{"k":"h","t":"«إنك تقدم على قوم أهل كتاب، فليكن أول ما تدعوهم إليه عبادة الله، فإذا عرفوا الله فأخبرهم...»","ref":"متفق عليه","id":"bukhari:1458"}]}]},{"id":"shurut","t":"العلم والرفق والصبر","intro":"قاعدة ذهبية ذكرها ابن تيمية: العلم قبل الأمر والنهي، والرفق معه، والصبر بعده.","points":[{"t":"كلام ابن تيمية","d":"","ev":[{"k":"b","t":"… هود: آية 115) . فلا بد من هذه الثلاثة: العلم، والرفق، والصبر. العلم قبل الأمر والنهي، والرفق معه، والصبر بعده، وإن كان كل من الثلاثة مستصحبا في هذه الأحوال؛ وهذا كما جاء في الأثر عن بعض السلف ورووه مرفوعا، ذكره القاضي أبو يعلى في المعتمد: \" لا يأمر بالمعروف وينهى عن المنكر إلا من كان فقيها فيما يأمر به، فقيها فيما ينهى عنه، رفيقا فيما يأمر به، رفيقا فيما ينهى عنه؛ حليما فيما يأمر به، حليما فيما ينهى عنه …","ref":"ابن تيمية في «الأمر بالمعروف والنهي عن المنكر»","id":"amr-maruf:3","sec":"الشروط الواجب توافرها في الآمر والناهي"}]},{"t":"الصبر على الأذى","d":"","ev":[{"k":"q","t":"يَـٰبُنَىَّ أَقِمِ ٱلصَّلَوٰةَ وَأْمُرْ بِٱلْمَعْرُوفِ وَٱنْهَ عَنِ ٱلْمُنكَرِ وَٱصْبِرْ عَلَىٰ مَآ أَصَابَكَ ۖ إِنَّ ذَٰلِكَ مِنْ عَزْمِ ٱلْأُمُورِ ﴿17﴾","ref":"لقمان: 17","id":"quran:31:17"}]}]},{"id":"qudwa","t":"القدوة قبل الكلمة","intro":"أقوى دعوة: أن يرى الناس أخلاق الإسلام فيك صدقاً وأمانة وإتقاناً.","points":[{"t":"لِمَ تقولون ما لا تفعلون","d":"","ev":[{"k":"q","t":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوا۟ لِمَ تَقُولُونَ مَا لَا تَفْعَلُونَ ﴿2﴾ كَبُرَ مَقْتًا عِندَ ٱللَّهِ أَن تَقُولُوا۟ مَا لَا تَفْعَلُونَ ﴿3﴾","ref":"الصف: 2–3","id":"quran:61:2"}]},{"t":"وما أريد أن أخالفكم","d":"","ev":[{"k":"q","t":"قَالَ يَـٰقَوْمِ أَرَءَيْتُمْ إِن كُنتُ عَلَىٰ بَيِّنَةٍ مِّن رَّبِّى وَرَزَقَنِى مِنْهُ رِزْقًا حَسَنًا ۚ وَمَآ أُرِيدُ أَنْ أُخَالِفَكُمْ إِلَىٰ مَآ أَنْهَىٰكُمْ عَنْهُ ۚ إِنْ أُرِيدُ إِلَّا ٱلْإِصْلَـٰحَ مَا ٱسْتَطَعْتُ ۚ وَمَا تَوْفِيقِىٓ إِلَّا بِٱللَّهِ ۚ عَلَيْهِ تَوَكَّلْتُ وَإِلَيْهِ أُنِيبُ ﴿88﴾","ref":"هود: 88","id":"quran:11:88"}]}]},{"id":"mukhatab","t":"مراعاة حال المخاطب ولغته","intro":"خاطب كل إنسان بما يفهم، وبلغته، وبما يناسب ثقافته وسنه.","points":[{"t":"بلسان قومه","d":"","ev":[{"k":"q","t":"وَمَآ أَرْسَلْنَا مِن رَّسُولٍ إِلَّا بِلِسَانِ قَوْمِهِۦ لِيُبَيِّنَ لَهُمْ ۖ فَيُضِلُّ ٱللَّهُ مَن يَشَآءُ وَيَهْدِى مَن يَشَآءُ ۚ وَهُوَ ٱلْعَزِيزُ ٱلْحَكِيمُ ﴿4﴾","ref":"إبراهيم: 4","id":"quran:14:4"}]}]},{"id":"shabab","t":"للشباب والفتيات: كيف تكون داعية؟","intro":"الشباب حملوا الدعوة الأولى: مصعب بن عمير سفير المدينة، والأرقم فتح بيته، وأم سليم دعت زوجها فأسلم.","points":[{"t":"أصحاب الكهف فتية","d":"","ev":[{"k":"q","t":"نَّحْنُ نَقُصُّ عَلَيْكَ نَبَأَهُم بِٱلْحَقِّ ۚ إِنَّهُمْ فِتْيَةٌ ءَامَنُوا۟ بِرَبِّهِمْ وَزِدْنَـٰهُمْ هُدًى ﴿13﴾","ref":"الكهف: 13","id":"quran:18:13"}]},{"t":"الفتيات داعيات: أم سليم","d":"كانت أم سليم سبب إسلام أبي طلحة، فكان إسلامه مهرها.","ev":[{"k":"h","t":"«فكان ذلك مهرها»، أي إسلام أبي طلحة","ref":"رواه النسائي","id":"nasai:3341"}]},{"t":"دعوة الأقران","d":"ابدأ بأصدقائك بالحب والهدية والكلمة الطيبة، وكن صادقاً في نصحك سراً لا علناً.","ev":[{"k":"q","t":"وَٱلْمُؤْمِنُونَ وَٱلْمُؤْمِنَـٰتُ بَعْضُهُمْ أَوْلِيَآءُ بَعْضٍ ۚ يَأْمُرُونَ بِٱلْمَعْرُوفِ وَيَنْهَوْنَ عَنِ ٱلْمُنكَرِ وَيُقِيمُونَ ٱلصَّلَوٰةَ وَيُؤْتُونَ ٱلزَّكَوٰةَ وَيُطِيعُونَ ٱللَّهَ وَرَسُولَهُۥٓ ۚ أُو۟لَـٰٓئِكَ سَيَرْحَمُهُمُ ٱللَّهُ ۗ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ ﴿71﴾","ref":"التوبة: 71","id":"quran:9:71"}]}]},{"id":"kibar","t":"دعوة الكبار والوالدين","intro":"دعوة الوالدين والكبار بالبر والأدب والدعاء، لا بالتعالي والجدال.","points":[{"t":"إبراهيم يدعو أباه بأرق الكلمات","d":"","ev":[{"k":"q","t":"إِذْ قَالَ لِأَبِيهِ يَـٰٓأَبَتِ لِمَ تَعْبُدُ مَا لَا يَسْمَعُ وَلَا يُبْصِرُ وَلَا يُغْنِى عَنكَ شَيْـًٔا ﴿42﴾ يَـٰٓأَبَتِ إِنِّى قَدْ جَآءَنِى مِنَ ٱلْعِلْمِ مَا لَمْ يَأْتِكَ فَٱتَّبِعْنِىٓ أَهْدِكَ صِرَٰطًا سَوِيًّا ﴿43﴾ يَـٰٓأَبَتِ لَا تَعْبُدِ ٱلشَّيْطَـٰنَ ۖ إِنَّ ٱلشَّيْطَـٰنَ كَانَ لِلرَّحْمَـٰنِ عَصِيًّا ﴿44﴾ يَـٰٓأَبَتِ إِنِّىٓ أَخَافُ أَن يَمَسَّكَ عَذَابٌ مِّنَ ٱلرَّحْمَـٰنِ فَتَكُونَ لِلشَّيْطَـٰنِ وَلِيًّا ﴿45﴾","ref":"مريم: 42–45","id":"quran:19:42"}]},{"t":"أبو هريرة وأمه","d":"دعا أبو هريرة أمه فأبت، فطلب دعاء النبي ﷺ فأسلمت.","ev":[{"k":"h","t":"«اللهم اهدِ أم أبي هريرة»","ref":"رواه مسلم","id":"muslim:6396"}]},{"t":"وصاحبهما في الدنيا معروفاً","d":"","ev":[{"k":"q","t":"وَإِن جَـٰهَدَاكَ عَلَىٰٓ أَن تُشْرِكَ بِى مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ فَلَا تُطِعْهُمَا ۖ وَصَاحِبْهُمَا فِى ٱلدُّنْيَا مَعْرُوفًا ۖ وَٱتَّبِعْ سَبِيلَ مَنْ أَنَابَ إِلَىَّ ۚ ثُمَّ إِلَىَّ مَرْجِعُكُمْ فَأُنَبِّئُكُم بِمَا كُنتُمْ تَعْمَلُونَ ﴿15﴾","ref":"لقمان: 15","id":"quran:31:15"}]}]},{"id":"atfal","t":"دعوة الأطفال والقريبين","intro":"زار النبي ﷺ غلاماً يهودياً مريضاً فدعاه إلى الإسلام فأسلم.","points":[{"t":"الغلام اليهودي","d":"","ev":[{"k":"h","t":"«الحمد لله الذي أنقذه من النار»","ref":"رواه البخاري","id":"bukhari:1356"}]}]},{"id":"akhta","t":"أخطاء يقع فيها الدعاة","intro":"التعنيف، والتشهير بالناس، والجدال للغلبة، والكلام بغير علم، واليأس من الناس، وتنفير المبتدئ بالتفاصيل.","points":[{"t":"لا تقف ما ليس لك به علم","d":"","ev":[{"k":"q","t":"وَلَا تَقْفُ مَا لَيْسَ لَكَ بِهِۦ عِلْمٌ ۚ إِنَّ ٱلسَّمْعَ وَٱلْبَصَرَ وَٱلْفُؤَادَ كُلُّ أُو۟لَـٰٓئِكَ كَانَ عَنْهُ مَسْـُٔولًا ﴿36﴾","ref":"الإسراء: 36","id":"quran:17:36"}]},{"t":"إنك لا تهدي من أحببت","d":"الهداية بيد الله، وعليك البلاغ؛ فلا تيأس ولا تحزن.","ev":[{"k":"q","t":"إِنَّكَ لَا تَهْدِى مَنْ أَحْبَبْتَ وَلَـٰكِنَّ ٱللَّهَ يَهْدِى مَن يَشَآءُ ۚ وَهُوَ أَعْلَمُ بِٱلْمُهْتَدِينَ ﴿56﴾","ref":"القصص: 56","id":"quran:28:56"},{"k":"q","t":"فَذَكِّرْ إِنَّمَآ أَنتَ مُذَكِّرٌ ﴿21﴾ لَّسْتَ عَلَيْهِم بِمُصَيْطِرٍ ﴿22﴾","ref":"الغاشية: 21–22","id":"quran:88:21"}]}]},{"id":"munazara","t":"آداب الحوار والمناظرة","intro":"المقصود إظهار الحق لا الانتصار للنفس: أنصِت، وافهم قول محاورك، واعترف بالصواب، واترك الجدال إذا صار مراءً.","points":[{"t":"ولا تجادلوا إلا بالتي هي أحسن","d":"","ev":[{"k":"q","t":"وَلَا تُجَـٰدِلُوٓا۟ أَهْلَ ٱلْكِتَـٰبِ إِلَّا بِٱلَّتِى هِىَ أَحْسَنُ إِلَّا ٱلَّذِينَ ظَلَمُوا۟ مِنْهُمْ ۖ وَقُولُوٓا۟ ءَامَنَّا بِٱلَّذِىٓ أُنزِلَ إِلَيْنَا وَأُنزِلَ إِلَيْكُمْ وَإِلَـٰهُنَا وَإِلَـٰهُكُمْ وَٰحِدٌ وَنَحْنُ لَهُۥ مُسْلِمُونَ ﴿46﴾","ref":"العنكبوت: 46","id":"quran:29:46"}]},{"t":"ترك المراء","d":"","ev":[{"k":"h","t":"«أنا زعيم ببيت في رَبَض الجنة لمن ترك المراء وإن كان محقاً»","ref":"رواه أبو داود","id":"abudawud:4800"}]},{"t":"وإنا أو إياكم لعلى هدى","d":"أدب القرآن في الحوار: لا تبدأ باتهام المخاطب.","ev":[{"k":"q","t":"قُلْ مَن يَرْزُقُكُم مِّنَ ٱلسَّمَـٰوَٰتِ وَٱلْأَرْضِ ۖ قُلِ ٱللَّهُ ۖ وَإِنَّآ أَوْ إِيَّاكُمْ لَعَلَىٰ هُدًى أَوْ فِى ضَلَـٰلٍ مُّبِينٍ ﴿24﴾","ref":"سبأ: 24","id":"quran:34:24"}]}]},{"id":"wasail","t":"الدعوة عبر وسائل التواصل","intro":"انشر الآيات والأحاديث الصحيحة والمعاني النافعة، وتحقق قبل النشر، وتجنب الجدال العقيم في التعليقات، واجعل حسابك قدوة.","points":[{"t":"التثبت قبل النشر","d":"","ev":[{"k":"q","t":"يَـٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُوٓا۟ إِن جَآءَكُمْ فَاسِقٌۢ بِنَبَإٍ فَتَبَيَّنُوٓا۟ أَن تُصِيبُوا۟ قَوْمًۢا بِجَهَـٰلَةٍ فَتُصْبِحُوا۟ عَلَىٰ مَا فَعَلْتُمْ نَـٰدِمِينَ ﴿6﴾","ref":"الحجرات: 6","id":"quran:49:6"}]}]},{"id":"amal","t":"الدعوة في العمل والجيرة والسفر","intro":"أخلاقك في عملك وتعاملك وأمانتك دعوة صامتة؛ فقد دخل كثير من الناس الإسلام بأخلاق التجار المسلمين.","points":[{"t":"الإحسان إلى الجار","d":"","ev":[{"k":"h","t":"«ما زال جبريل يوصيني بالجار حتى ظننت أنه سيورّثه»","ref":"متفق عليه","id":"bukhari:6015"}]},{"t":"وقولوا للناس حسناً","d":"","ev":[{"k":"q","t":"وَإِذْ أَخَذْنَا مِيثَـٰقَ بَنِىٓ إِسْرَٰٓءِيلَ لَا تَعْبُدُونَ إِلَّا ٱللَّهَ وَبِٱلْوَٰلِدَيْنِ إِحْسَانًا وَذِى ٱلْقُرْبَىٰ وَٱلْيَتَـٰمَىٰ وَٱلْمَسَـٰكِينِ وَقُولُوا۟ لِلنَّاسِ حُسْنًا وَأَقِيمُوا۟ ٱلصَّلَوٰةَ وَءَاتُوا۟ ٱلزَّكَوٰةَ ثُمَّ تَوَلَّيْتُمْ إِلَّا قَلِيلًا مِّنكُمْ وَأَنتُم مُّعْرِضُونَ ﴿83﴾","ref":"البقرة: 83","id":"quran:2:83"}]}]},{"id":"muslim-jadid","t":"مع المسلم الجديد","intro":"استقبله بالفرح، وعلّمه الأهم فالأهم: التوحيد، ثم الصلاة، ثم ما يحتاجه؛ ولا تثقل عليه، وكن له أخاً وسنداً.","points":[{"t":"التدرج من وصية معاذ","d":"","ev":[{"k":"h","t":"«فليكن أول ما تدعوهم إليه عبادة الله، فإذا عرفوا الله فأخبرهم أن الله قد فرض عليهم خمس صلوات...»","ref":"متفق عليه","id":"bukhari:1458"}]},{"t":"الإسلام يجبّ ما قبله","d":"","ev":[{"k":"h","t":"«أما علمت أن الإسلام يهدم ما كان قبله؟»","ref":"رواه مسلم","id":"muslim:321"}]}]}]}],"tips":{"ahl":["ابدأ بنقاط الاتفاق: الإيمان بالله، والأنبياء، والأخلاق.","اسأل أكثر مما تتكلم: «ما الذي تعرفه عن الإسلام؟»","أهدِ ترجمة لمعاني القرآن بلغته، أو كتاباً تعريفياً موثوقاً.","لا تحرج محاورك أمام الناس، واترك له مساحة للتفكير.","ادعُ له بالهداية سراً، فالقلوب بيد الله."],"mulhid":["افهم سبب إلحاده أولاً: شبهة عقلية، أم تجربة مؤلمة، أم تقليد؟ فلكل علاج.","ابدأ بسؤال الوجود: من أين جاء الكون؟ قبل الدخول في التفاصيل.","لا تسخر ولا تغضب، فالهدوء أقوى حجة.","إذا لم تعرف الجواب فقل: «سأبحث وأعود إليك»، ثم ارجع إلى أهل العلم.","اربطه بالمعنى والغاية، فكثيرون يبحثون عن طمأنينة لا عن جدال."],"turuq":["ابدأ بنفسك: صلاتك وأخلاقك هي دعوتك الأولى.","تعلّم قبل أن تتكلم، واستعن بكتب المكتبة.","استخدم وسائل التواصل بنشر الخير والآيات والأحاديث الصحيحة فقط، وتحقق قبل النشر.","اختر الوقت المناسب، والكلمة القصيرة، والأسلوب اللطيف.","ادعُ بالحال: الابتسامة، والهدية، وقضاء الحاجة، تفتح القلوب قبل الكلام."]},"card":"الإسلام دين الله الذي أرسل به جميع الأنبياء: نوحاً وإبراهيم وموسى وعيسى ومحمداً عليهم السلام.\nيدعو إلى عبادة الله وحده لا شريك له، الخالق الرحيم، بلا وسيط بين العبد وربه.\nيؤمن المسلم بالمسيح عيسى ابن مريم نبياً كريماً، وبأمه الطاهرة مريم، وبجميع الكتب التي أنزلها الله.\nأركانه: الشهادتان، والصلاة، والزكاة، والصيام، والحج.\nالقرآن كلام الله المحفوظ، ومحمد ﷺ خاتم الأنبياء، أُرسل رحمة للعالمين.\n﴿قل هو الله أحد ۝ الله الصمد ۝ لم يلد ولم يولد ۝ ولم يكن له كفواً أحد﴾"};
